(window.__COUR = window.__COUR || {})["data/cas.json"] = [{"id":"atlas","matiere":"affaires","title":"TechMaroc c/ Atlas Fret","court":"Tribunal de commerce — chambre commerciale","object":"Rupture abusive d'une relation commerciale établie. Demande de 500 000 DH de dommages et intérêts.","you":"Avocat de la défense (Atlas Fret)","adverseName":"Avocat de TechMaroc","facts":"Atlas Fret (logistique) a rompu un contrat de 3 ans avec son prestataire informatique TechMaroc par un simple e-mail, avec un préavis de 48 heures, en invoquant des dysfonctionnements techniques. TechMaroc saisit la justice.","rounds":[{"name":"Plaidoirie de la demande","adverse":"Monsieur le Président, Honorables Juges. La société Atlas Fret a rompu unilatéralement et brutalement une relation commerciale établie depuis trois ans, avec un préavis réduit à quarante-huit heures, notifié par un simple courriel. Cette rupture, sans mise en demeure ni délai de régularisation, constitue un abus de droit et une violation de l'obligation de bonne foi du Dahir des Obligations et Contrats. Nous demandons 500 000 Dirhams de dommages et intérêts.","prompt":"Présentez la réplique de la défense.","options":[{"label":"Contester sur le fond","detail":"Invoquer l'inexécution grave de TechMaroc et l'article 259 du DOC.","pts":15,"speech":"Monsieur le Président, cher Confrère. Atlas Fret conteste le caractère abusif de la rupture. En vertu de l'article 259 du DOC, l'inexécution répétée et grave de TechMaroc, dont la plateforme a paralysé notre chaîne logistique, rendait impossible la poursuite du contrat.","ok":["Fondement juridique pertinent (art. 259 DOC)","Met en avant la gravité de l'inexécution"],"ko":["Ne traite pas encore l'absence de mise en demeure"]},{"label":"Attaquer sur la forme","detail":"Soulever l'incompétence du tribunal de commerce.","pts":6,"speech":"Monsieur le Président, la défense soulève à titre liminaire l'incompétence de cette juridiction pour connaître du présent litige.","ok":["Réflexe procédural"],"ko":["Exception mal fondée : litige entre commerçants pour un acte de commerce","Laisse le fond sans réponse"]}],"concepts":[{"label":"Invoque l'inexécution / les dysfonctionnements de TechMaroc","re":"inexecution|dysfonction|panne|defaillan|manquement","pts":6,"key":true},{"label":"Souligne la gravité de la faute","re":"grav|faute grave|paralys|bloqu","pts":4},{"label":"Évoque des preuves des incidents","re":"preuve|rapport|ticket|incident|constat|pieces?","pts":3},{"label":"Répond sur la bonne foi","re":"bonne foi|loyaut","pts":3}],"articles":[{"code":"DOC","article":"259","label":"Art. 259 DOC (exécution forcée ou résolution)","pts":4}],"faille":"La défense invoque des dysfonctionnements, mais où sont les pièces ? Aucun constat, aucun rapport d'incident n'est versé aux débats.","concede":"La défense invoque l'inexécution. Soit. Encore faut-il qu'elle ait respecté la procédure qui l'encadre."},{"name":"Contre-attaque : la mise en demeure","adverse":"Si l'article 259 du DOC autorise la résolution en cas d'inexécution, encore faut-il que le débiteur soit en demeure. Or Atlas Fret ne produit aucune interpellation écrite lui laissant un délai pour corriger, seulement cet e-mail de 48 heures.","prompt":"Répondez à l'argument de l'absence de mise en demeure.","options":[{"label":"Produire les échanges écrits","detail":"Tickets et e-mails de réclamation ; liberté de la preuve en matière commerciale.","pts":17,"speech":"La défense verse aux débats quatorze tickets d'incident et six e-mails de réclamation adressés à TechMaroc sur quatre mois. En matière commerciale, la preuve est libre : ces écrits démontrent que le prestataire connaissait ses manquements et disposait de délais pour y remédier.","ok":["Neutralise l'argument de l'absence de mise en demeure","Utilise la liberté de la preuve commerciale"],"ko":["Les réclamations ne fixaient pas de délai formel"]},{"label":"Invoquer la gravité seule","detail":"Soutenir que la gravité de la faute dispense de toute mise en demeure.","pts":8,"speech":"La gravité exceptionnelle des manquements dispensait Atlas Fret de toute mise en demeure préalable.","ok":["Argument recevable en théorie"],"ko":["Aucune pièce pour prouver la gravité alléguée","Laisse ouverte la faille de forme"]}],"concepts":[{"label":"Répond sur la mise en demeure","re":"mise en demeure|interpell|mettre en demeure|notifi","pts":5,"key":true},{"label":"Produit des écrits (e-mails, tickets, réclamations)","re":"e-?mail|courriel|ticket|reclamation|ecrit|lettre","pts":6},{"label":"Invoque la liberté de la preuve commerciale","re":"liberte de la preuve|preuve (est )?libre|tous moyens","pts":4}],"articles":[{"code":"CCOM","article":"334","label":"Art. 334 Code de commerce (liberté de la preuve)","pts":3},{"code":"DOC","article":"255","label":"Art. 255 DOC (demeure du débiteur)","pts":2}],"faille":"La défense n'a toujours rien produit qui ressemble à une mise en demeure. La rupture reste fautive dans sa forme.","concede":"Les pièces montrent des échanges. Mais elles ne fixaient aucun délai : le préavis de 48 heures reste brutal."},{"name":"Le montant réclamé","adverse":"Le préjudice de TechMaroc est considérable : perte du client principal, licenciement de deux ingénieurs, atteinte à sa réputation. Les 500 000 Dirhams réclamés sont la juste réparation de cette rupture brutale.","prompt":"Plaidez sur le montant des dommages et intérêts.","options":[{"label":"Contester le montant","detail":"Disproportion avec le chiffre d'affaires réel ; préjudice non justifié ; subsidiairement, réduction.","pts":18,"speech":"À titre subsidiaire, 500 000 Dirhams sont sans rapport avec le chiffre d'affaires réalisé avec Atlas Fret sur douze mois, soit 210 000 Dirhams. Aucun justificatif des licenciements ni de l'atteinte à la réputation n'est produit. Le préjudice, s'il existe, se limite au défaut de préavis.","ok":["Chiffre la disproportion","Exige la preuve du préjudice","Plaide à titre subsidiaire"],"ko":[]},{"label":"Demande reconventionnelle","detail":"Réclamer à TechMaroc une indemnisation pour le préjudice logistique.","pts":10,"speech":"Atlas Fret forme une demande reconventionnelle : c'est elle qui a subi un préjudice logistique du fait des pannes répétées.","ok":["Démarche offensive"],"ko":["Demande non chiffrée et sans pièces","Ne conteste pas directement les 500 000 DH"]}],"concepts":[{"label":"Conteste le montant / la disproportion","re":"disproportion|excessi|exager|montant|chiffre d.affaires","pts":5,"key":true},{"label":"Exige la preuve du préjudice","re":"prejudice.*(prouv|justifi|demontr)|(prouv|justifi|demontr).*prejudice|aucun justificatif","pts":5},{"label":"Plaide à titre subsidiaire / réduction","re":"subsidiair|reduir|reduction|limit","pts":4},{"label":"Lie le préjudice au seul défaut de préavis","re":"preavis","pts":3}],"articles":[{"code":"DOC","article":"264","label":"Art. 264 DOC (évaluation des dommages)","pts":3}],"faille":"La défense ne conteste même pas sérieusement le chiffrage. Le tribunal retiendra le montant demandé.","concede":"Le chiffrage peut être discuté, mais le principe de la réparation demeure."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu qu'Atlas Fret justifie de réclamations écrites répétées, mais que le préavis de quarante-huit heures demeure insuffisant au regard de la durée de la relation ; constate que le préjudice allégué n'est que partiellement justifié ; Par ces motifs : condamne Atlas Fret à verser 25 000 Dirhams au titre du seul défaut de préavis."},{"min":45,"text":"Le Tribunal, attendu que la rupture d'un partenariat de longue durée exige un préavis raisonnable et une mise en demeure préalable, dont la preuve n'est pas rapportée ; retient toutefois que la somme de 500 000 Dirhams est disproportionnée ; Par ces motifs : condamne Atlas Fret à verser 50 000 Dirhams de dommages et intérêts."},{"min":0,"text":"Le Tribunal, attendu qu'Atlas Fret ne justifie ni des manquements allégués ni d'aucune mise en demeure, et n'a pas utilement contesté le préjudice ; Par ces motifs : qualifie la rupture d'abusive et condamne Atlas Fret à verser 180 000 Dirhams, outre les dépens."}]},{"id":"sahara","matiere":"affaires","title":"Sahara Textiles c/ Boutique Anfa","court":"Tribunal de commerce de Casablanca","object":"Recouvrement de factures impayées : 240 000 DH de marchandises livrées.","you":"Avocat de la demande (Sahara Textiles)","adverseName":"Avocat de Boutique Anfa","facts":"Sahara Textiles SARL a livré à Boutique Anfa trois lots de tissus entre janvier et mars. Les factures, d'un total de 240 000 DH, restent impayées malgré une lettre de mise en demeure. Boutique Anfa a versé un acompte de 30 000 DH en février, puis plus rien.","rounds":[{"name":"Exception de la défense : la preuve","adverse":"Monsieur le Président, la demanderesse ne produit aucun bon de commande signé par ma cliente. Des factures établies unilatéralement ne prouvent rien. La demande doit être rejetée faute de preuve de l'obligation.","prompt":"Établissez l'existence de la créance.","options":[{"label":"Liberté de la preuve","detail":"Bons de livraison signés, acompte versé, preuve libre entre commerçants.","pts":18,"speech":"Entre commerçants, la preuve est libre. Nous produisons les trois bons de livraison signés et tamponnés par Boutique Anfa, ainsi que son virement de 30 000 Dirhams en février, qui vaut reconnaissance de la relation et de la dette.","ok":["Mobilise la liberté de la preuve commerciale","Produit des pièces signées par l'adversaire","L'acompte vaut reconnaissance"],"ko":[]},{"label":"S'en tenir aux factures","detail":"Rappeler que les factures ont été envoyées et jamais contestées.","pts":8,"speech":"Les factures ont été adressées à la défenderesse, qui ne les a jamais contestées.","ok":["L'absence de contestation est un indice"],"ko":["Aucune pièce émanant du débiteur","N'utilise pas les bons de livraison"]}],"concepts":[{"label":"Produit des bons de livraison / pièces signées","re":"bons? de livraison|signe|tampon|cachet|accuse de reception","pts":6,"key":true},{"label":"Invoque la liberté de la preuve commerciale","re":"liberte de la preuve|preuve (est )?libre|tous moyens|entre commercants","pts":5},{"label":"Utilise l'acompte ou une reconnaissance","re":"paiement partiel|acompte|virement|reconnaiss","pts":4}],"articles":[{"code":"CCOM","article":"334","label":"Art. 334 Code de commerce (liberté de la preuve)","pts":5}],"faille":"La demande ne produit rien qui émane de ma cliente. Une facture ne se prouve pas par elle-même.","concede":"Admettons que les livraisons aient eu lieu. Encore faut-il que la marchandise ait été conforme."},{"name":"Exception d'inexécution : marchandise défectueuse","adverse":"Subsidiairement, les tissus du troisième lot présentaient des défauts de teinture. Ma cliente était donc fondée à suspendre son paiement en application de l'exception d'inexécution.","prompt":"Répondez à l'allégation de marchandise défectueuse.","options":[{"label":"Réception sans réserve","detail":"Marchandise acceptée sans réserves, réclamation inexistante, revente déjà effectuée.","pts":17,"speech":"Les bons de livraison ont été signés sans aucune réserve. Aucune réclamation n'a été formulée dans les jours suivant la réception, et la défenderesse a revendu l'essentiel des tissus. On ne peut à la fois vendre une marchandise et la dire inutilisable.","ok":["Réception sans réserve","Réclamation tardive","Contradiction de l'adversaire (revente)"],"ko":["Ne propose pas d'expertise pour clore le débat"]},{"label":"Demander une expertise","detail":"Solliciter une expertise judiciaire sur la qualité des tissus.","pts":10,"speech":"La demanderesse sollicite une expertise judiciaire afin d'établir la conformité des tissus livrés.","ok":["Démarche prudente"],"ko":["Retarde la procédure","Reprend à son compte une preuve qui pèse sur l'adversaire"]}],"concepts":[{"label":"Réception sans réserve","re":"sans (aucune )?reserve|accept","pts":6,"key":true},{"label":"Réclamation tardive ou inexistante","re":"tardi|delai|aucune reclamation|jamais (conteste|reclame)","pts":5},{"label":"Relève la revente / la contradiction","re":"revend|revente|contradi","pts":4}],"articles":[{"code":"DOC","article":"235","label":"Art. 235 DOC (exception d'inexécution)","pts":5}],"faille":"La demande ne répond pas sur les défauts. L'exception d'inexécution reste entière.","concede":"Les tissus ont été réceptionnés sans réserve, c'est exact. Mais le montant réclamé reste discutable."},{"name":"Les intérêts et le montant","adverse":"Enfin, la demanderesse réclame des intérêts et des dommages sans fondement. Ma cliente traverse des difficultés de trésorerie ; nous demandons des délais de paiement.","prompt":"Fixez vos demandes chiffrées.","options":[{"label":"Principal + intérêts","detail":"210 000 DH restant dus, dommages pour retard depuis la mise en demeure, rejet des délais.","pts":17,"speech":"Nous demandons le solde de 210 000 Dirhams, déduction faite de l'acompte, avec des dommages pour retard à compter de la mise en demeure. Des difficultés de trésorerie ne justifient pas de nouveaux délais à un débiteur qui a déjà revendu la marchandise.","ok":["Chiffrage exact (déduction de l'acompte)","Point de départ de la demeure","Répond à la demande de délais"],"ko":[]},{"label":"Dommages forfaitaires","detail":"Réclamer 500 000 DH pour le préjudice global subi.","pts":6,"speech":"Nous demandons 500 000 Dirhams pour l'ensemble du préjudice subi par notre cliente.","ok":[],"ko":["Montant sans rapport avec la créance","Aucun justificatif","Décrédibilise la demande principale"]}],"concepts":[{"label":"Chiffre le principal (déduction de l'acompte)","re":"210|solde|deduction|deduit|principal","pts":5,"key":true},{"label":"Demande les intérêts / dommages pour retard","re":"interets?|retard","pts":4},{"label":"Fixe le point de départ (mise en demeure)","re":"mise en demeure","pts":3},{"label":"S'oppose aux délais de paiement","re":"delai|tresorerie","pts":3}],"articles":[{"code":"DOC","article":"263","label":"Art. 263 DOC (dommages pour inexécution ou retard)","pts":5}],"faille":"La demande ne chiffre rien de précis. Le tribunal ne peut accorder ce qu'on ne lui demande pas clairement.","concede":"Nous prenons acte du chiffrage et nous en remettons à la sagesse du tribunal."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la livraison est établie par des bons signés sans réserve et que l'acompte vaut reconnaissance de la dette ; que l'exception d'inexécution n'est pas justifiée ; Par ces motifs : condamne Boutique Anfa à payer 210 000 Dirhams, avec dommages pour retard à compter de la mise en demeure, et rejette la demande de délais."},{"min":45,"text":"Le Tribunal, attendu que la livraison est établie, mais que la demanderesse n'a pas répondu sur l'ensemble des contestations ; Par ces motifs : condamne Boutique Anfa à payer 210 000 Dirhams, accorde un délai de six mois et rejette le surplus."},{"min":0,"text":"Le Tribunal, attendu que la demanderesse ne rapporte pas une preuve suffisante de sa créance ni de la conformité de la marchandise ; Par ces motifs : ordonne avant dire droit une expertise et réserve les dépens."}]},{"id":"cheque-impaye","matiere":"affaires","title":"Optique Médina c/ Ben Saïd","court":"Tribunal de commerce de Fès","object":"Recouvrement d'un chèque de 85 000 DH rejeté pour défaut de provision.","you":"Avocat du porteur (Optique Médina)","adverseName":"Avocat de M. Ben Saïd","facts":"M. Ben Saïd, commerçant, a remis à Optique Médina un chèque de 85 000 DH en paiement d'un lot de montures. Présenté dans les délais, le chèque a été rejeté pour défaut de provision et un protêt a été dressé. Optique Médina a prévenu le tireur par lettre recommandée cinq jours plus tard, puis l'a assigné sept mois après l'expiration du délai de présentation.","rounds":[{"name":"L'action cambiaire est-elle recevable ?","adverse":"Monsieur le Président, le porteur a laissé passer plus de six mois après l'expiration du délai de présentation avant d'agir. L'action en recours fondée sur le chèque est prescrite. La demande doit être déclarée irrecevable.","prompt":"Répondez à l'exception de prescription.","options":[{"label":"Basculer sur l'action de droit commun","detail":"Admettre la prescription cambiaire mais agir sur la vente (créance fondamentale).","pts":17,"speech":"Nous ne contestons pas que l'action cambiaire contre le tireur se prescrit par six mois. Mais la créance de prix née de la vente des montures subsiste : le chèque n'a pas éteint la dette tant qu'il n'a pas été payé. Nous agissons donc sur le fondement du contrat de vente, dont la livraison est prouvée par le bon signé.","ok":["Distingue rapport cambiaire et créance fondamentale","Reconnaît loyalement la prescription","S'appuie sur la preuve de la livraison"],"ko":[]},{"label":"Nier la prescription","detail":"Soutenir que le délai de six mois n'est pas écoulé.","pts":5,"speech":"Le délai de prescription n'est pas expiré, l'action est parfaitement recevable.","ok":[],"ko":["Contredit les dates du dossier","Perd en crédibilité devant le tribunal"]}],"concepts":[{"label":"Distingue l'action cambiaire et la créance de la vente","re":"vente|contrat|creance (fondamentale|initiale|de prix)|rapport fondamental|droit commun","pts":6,"key":true},{"label":"Reconnaît la prescription de six mois","re":"six mois|6 mois|prescri","pts":4},{"label":"Prouve la livraison / la dette","re":"livraison|bon|facture","pts":4}],"articles":[{"code":"CCOM","article":"295","label":"Art. 295 Code de commerce (prescription des recours : six mois)","pts":4}],"faille":"Le porteur ne propose aucun autre fondement : sa demande tombe avec la prescription du chèque.","concede":"Soit, la créance de prix demeure. Mais encore faut-il qu'elle soit exigible."},{"name":"Le préavis au tireur","adverse":"Subsidiairement, le porteur n'a pas averti le tireur du défaut de paiement dans le délai légal. Cette négligence a privé mon client de la possibilité de régulariser.","prompt":"Répondez sur l'avis du défaut de paiement.","options":[{"label":"Avis donné dans le délai","detail":"Lettre recommandée envoyée cinq jours après le protêt, dans le délai de huit jours ouvrables.","pts":16,"speech":"L'avis du défaut de paiement a été adressé au tireur par lettre recommandée cinq jours après le protêt, soit dans le délai de huit jours ouvrables. Au surplus, l'omission de l'avis n'entraîne pas la déchéance du porteur : elle l'expose seulement à réparer le préjudice causé par sa négligence, que l'adversaire ne démontre pas.","ok":["Produit l'accusé de réception","Respect du délai de huit jours","Rappelle que l'omission n'entraîne pas la déchéance"],"ko":[]},{"label":"Ignorer l'argument","detail":"Plaider directement sur le montant.","pts":6,"speech":"Nous maintenons notre demande de 85 000 Dirhams.","ok":[],"ko":["Laisse l'argument adverse sans réponse"]}],"concepts":[{"label":"Avis envoyé dans les huit jours","re":"huit jours|8 jours|cinq jours|recommande|avis","pts":6,"key":true},{"label":"Pas de déchéance, seulement des dommages","re":"decheance|negligence|prejudice","pts":4},{"label":"Produit une preuve d'envoi","re":"accuse|recommande|preuve","pts":3}],"articles":[{"code":"CCOM","article":"285","label":"Art. 285 Code de commerce (avis du défaut de paiement)","pts":4}],"faille":"Le porteur ne justifie d'aucun avis : la négligence est établie.","concede":"L'avis a été donné à temps. Reste la question des intérêts."},{"name":"Les demandes chiffrées","adverse":"Mon client reconnaît devoir une partie de la somme, mais les montures livrées étaient en partie d'une autre référence. Il propose 60 000 Dirhams.","prompt":"Fixez vos demandes.","options":[{"label":"Principal et dommages pour retard","detail":"85 000 DH, dommages pour retard depuis la présentation, rejet de la réfaction non prouvée.","pts":17,"speech":"Le bon de livraison, signé sans réserve, mentionne les références commandées. La réfaction proposée n'est étayée par aucune réclamation. Nous demandons 85 000 Dirhams, avec des dommages pour retard à compter de la présentation du chèque.","ok":["S'appuie sur la réception sans réserve","Rejette une réfaction non prouvée","Point de départ cohérent"],"ko":[]},{"label":"Accepter 60 000 DH","detail":"Transiger immédiatement.","pts":9,"speech":"Notre cliente accepte la somme de 60 000 Dirhams.","ok":["Solution rapide"],"ko":["Abandonne 25 000 DH sans contrepartie","Aucune vérification de la réclamation"]}],"concepts":[{"label":"Maintient le principal de 85 000 DH","re":"85|principal|totalite","pts":5,"key":true},{"label":"Rejette la réfaction non prouvée","re":"sans reserve|aucune reclamation|non prouv|pas prouv","pts":4},{"label":"Demande des dommages pour retard","re":"retard|interets?","pts":4}],"articles":[{"code":"DOC","article":"263","label":"Art. 263 DOC (dommages pour retard)","pts":3}],"faille":"Le porteur ne justifie pas pourquoi la proposition serait insuffisante.","concede":"Nous prenons acte, le tribunal appréciera."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'action cambiaire est prescrite mais que la créance de prix née de la vente est établie par un bon de livraison signé sans réserve ; Par ces motifs : condamne M. Ben Saïd à payer 85 000 Dirhams, avec dommages pour retard à compter de la présentation du chèque."},{"min":45,"text":"Le Tribunal, attendu que la créance de prix est établie mais que le porteur n'a pas répondu à toutes les contestations ; Par ces motifs : condamne M. Ben Saïd à payer 85 000 Dirhams sans dommages pour retard."},{"min":0,"text":"Le Tribunal, attendu que l'action fondée sur le chèque est prescrite et qu'aucun autre fondement n'est utilement invoqué ; Par ces motifs : déclare la demande irrecevable."}]},{"id":"lettre-change","matiere":"affaires","title":"Banque Atlantique c/ Société Rif Bois","court":"Tribunal de commerce de Tanger","object":"Recours du porteur d'une lettre de change de 120 000 DH contre un endosseur.","you":"Avocat de l'endosseur (Rif Bois)","adverseName":"Avocat de Banque Atlantique","facts":"Rif Bois a endossé au profit de Banque Atlantique une lettre de change tirée sur un client. À l'échéance, le tiré n'a pas payé. La banque n'a fait dresser le protêt que trois semaines après l'échéance, sans invoquer de force majeure, puis s'est retournée contre Rif Bois.","rounds":[{"name":"Le recours contre l'endosseur","adverse":"Monsieur le Président, tous ceux qui ont endossé une lettre de change sont tenus solidairement envers le porteur. Rif Bois doit payer les 120 000 Dirhams.","prompt":"Présentez la défense de l'endosseur.","options":[{"label":"Protêt tardif","detail":"Le refus de paiement devait être constaté par un protêt dans les délais : le porteur négligent perd ses recours contre les endosseurs.","pts":17,"speech":"Le refus de paiement doit être constaté par un protêt dressé dans les délais légaux. La banque l'a fait établir trois semaines après l'échéance, sans aucune force majeure. Porteur négligent, elle a perdu ses recours contre les endosseurs, dont Rif Bois.","ok":["Identifie la tardiveté du protêt","Écarte la force majeure","Tire la conséquence : perte du recours contre l'endosseur"],"ko":[]},{"label":"Contester la solidarité","detail":"Soutenir que l'endosseur n'est jamais tenu.","pts":5,"speech":"Un endosseur n'a pas à garantir le paiement d'une dette qui n'est pas la sienne.","ok":[],"ko":["Contraire au principe de solidarité cambiaire","Ignore le vrai moyen de défense"]}],"concepts":[{"label":"Invoque le protêt tardif","re":"protet.*(tardi|delai|hors)|(tardi|delai|hors).*protet","pts":6,"key":true},{"label":"Écarte la force majeure","re":"force majeure","pts":4},{"label":"Conclut à la perte du recours (porteur négligent)","re":"negligent|perte|perd|decheance","pts":4}],"articles":[{"code":"CCOM","article":"197","label":"Art. 197 Code de commerce (protêt faute de paiement)","pts":2},{"code":"CCOM","article":"206","label":"Art. 206 Code de commerce (déchéance du porteur négligent)","pts":3},{"code":"CCOM","article":"207","label":"Art. 207 Code de commerce (force majeure)","pts":1}],"faille":"L'endosseur ne conteste rien de sérieux : la solidarité joue pleinement.","concede":"Le protêt est tardif, c'est vrai. Mais la banque garde d'autres droits."},{"name":"Les autres droits de la banque","adverse":"Même sans recours cambiaire, la banque a escompté cet effet et crédité le compte de Rif Bois : elle peut lui réclamer le remboursement au titre du compte.","prompt":"Répondez à ce nouveau fondement.","options":[{"label":"Exiger la preuve de l'escompte et du compte","detail":"Ce fondement relève du contrat bancaire : la banque doit le prouver et le chiffrer.","pts":15,"speech":"La banque change de fondement en cours d'audience. Si elle invoque une convention d'escompte, qu'elle la produise, ainsi que le relevé de compte montrant le crédit et sa contre-passation. À défaut, la demande n'est pas prouvée : la preuve de l'obligation incombe à celui qui s'en prévaut.","ok":["Relève le changement de fondement","Exige la convention et les relevés","Rappelle la charge de la preuve"],"ko":[]},{"label":"Reconnaître la dette","detail":"Admettre devoir le montant au titre du compte.","pts":6,"speech":"Notre cliente ne conteste pas avoir été créditée.","ok":[],"ko":["Abandonne la défense gagnée au premier round"]}],"concepts":[{"label":"Rappelle la charge de la preuve","re":"preuve|prouv","pts":5,"key":true},{"label":"Exige la convention / les relevés","re":"convention|releve|escompte|contrat","pts":5},{"label":"Relève le changement de fondement","re":"fondement|nouveau|change","pts":3}],"articles":[{"code":"DOC","article":"399","label":"Art. 399 DOC (charge de la preuve)","pts":4}],"faille":"L'endosseur ne conteste pas avoir été crédité : la créance est reconnue.","concede":"La banque produira ses relevés. Le tribunal appréciera."},{"name":"Conclusions finales","adverse":"La banque demande, à titre subsidiaire, des délais pour produire les relevés de compte.","prompt":"Concluez.","options":[{"label":"Rejet et, au plus, renvoi encadré","detail":"Rejet du recours cambiaire ; sur le compte, rejet faute de preuve ou délai strict.","pts":16,"speech":"Nous concluons au rejet du recours cambiaire, le protêt étant tardif. Sur le fondement du compte, la banque n'a rien produit : nous demandons le rejet, ou à tout le moins un délai strict avec avertissement que la demande sera écartée faute de pièces.","ok":["Conclusions claires et hiérarchisées","Encadre la demande de délai"],"ko":[]},{"label":"Ne rien conclure","detail":"Laisser le tribunal décider.","pts":7,"speech":"Nous nous en remettons à la sagesse du tribunal.","ok":[],"ko":["Aucune conclusion précise"]}],"concepts":[{"label":"Conclut au rejet du recours cambiaire","re":"rejet|irrecevab","pts":5,"key":true},{"label":"Encadre le délai demandé","re":"delai strict|bref delai|ecart|a defaut","pts":4}],"articles":[],"faille":"Faute de conclusions précises, le tribunal accordera les délais demandés.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le protêt faute de paiement a été dressé hors délai sans force majeure et que la banque, porteur négligent, a perdu son recours contre l'endosseur ; qu'elle ne prouve pas la créance invoquée au titre du compte ; Par ces motifs : rejette la demande."},{"min":45,"text":"Le Tribunal, attendu que le recours cambiaire est perdu mais que la banque peut justifier d'une créance de compte ; Par ces motifs : rejette le recours cambiaire et renvoie l'affaire pour production des relevés."},{"min":0,"text":"Le Tribunal, attendu que les endosseurs sont tenus solidairement et que la défense n'établit aucune cause de déchéance ; Par ces motifs : condamne Rif Bois à payer 120 000 Dirhams."}]},{"id":"bail-commercial","matiere":"affaires","title":"Café Les Palmiers c/ Mme El Fassi","court":"Tribunal de commerce de Marrakech","object":"Éviction d'un locataire commercial et indemnité de résiliation.","you":"Avocat du locataire (Café Les Palmiers)","adverseName":"Avocat de la bailleresse","facts":"Le Café Les Palmiers exploite depuis neuf ans un local appartenant à Mme El Fassi. Celle-ci a délivré congé pour « reprise », sans autre précision, avec un délai de quinze jours, puis a saisi le tribunal pour obtenir l'expulsion sans indemnité.","rounds":[{"name":"La validité du congé","adverse":"Monsieur le Président, ma cliente est propriétaire et souhaite reprendre son bien. Le congé a été délivré ; le locataire doit partir.","prompt":"Contestez le congé.","options":[{"label":"Congé irrégulier","detail":"Le congé doit exposer obligatoirement son motif et respecter le délai légal correspondant.","pts":17,"speech":"La loi impose au bailleur d'adresser un congé exposant obligatoirement le motif, avec le délai d'éviction prévu pour ce motif. Le congé se borne à évoquer une « reprise » sans dire pour quoi faire. Surtout, une reprise ouvre un délai de trois mois ; le délai de quinze jours est réservé au défaut de paiement des loyers ou au local menaçant ruine. Le congé est irrégulier.","ok":["Exige un motif précis","Vérifie le délai correspondant au motif"],"ko":[]},{"label":"Plaider l'ancienneté seule","detail":"Neuf ans d'exploitation empêchent l'éviction.","pts":8,"speech":"Après neuf ans, le locataire ne peut pas être évincé.","ok":["Valorise l'ancienneté"],"ko":["L'ancienneté n'interdit pas l'éviction","Ne critique pas le congé"]}],"concepts":[{"label":"Exige un motif exposé dans le congé","re":"motif","pts":6,"key":true},{"label":"Conteste le délai : trois mois pour une reprise, pas quinze jours","re":"trois mois|3 mois|quinze|15 jours|delai","pts":5},{"label":"Conclut à l'irrégularité / nullité du congé","re":"irregul|nul|invalide","pts":3}],"articles":[{"code":"L49-16","article":"26","label":"Art. 26 loi 49-16 (congé motivé et délais)","pts":4}],"faille":"Le locataire ne critique pas sérieusement le congé : il est valable.","concede":"Le congé est imparfait. Mais la bailleresse peut le régulariser."},{"name":"Le droit à indemnité","adverse":"Quand bien même, la reprise par la propriétaire est un droit : aucune indemnité n'est due.","prompt":"Défendez le droit à indemnité.","options":[{"label":"Indemnité de résiliation","detail":"Le locataire évincé a droit à une indemnité égale au préjudice, incluant la valeur du fonds.","pts":18,"speech":"La loi pose le principe : le locataire a droit à une indemnité de résiliation, qui correspond au préjudice subi du fait de l'éviction et comprend la valeur du fonds de commerce. La bailleresse n'invoque aucune des exceptions légales. Nous demandons une expertise pour évaluer le fonds.","ok":["Pose le principe légal","Relève l'absence d'exception","Demande une expertise d'évaluation"],"ko":[]},{"label":"Demander un montant forfaitaire","detail":"Réclamer 2 millions de DH sans justification.","pts":7,"speech":"Nous réclamons deux millions de Dirhams.","ok":[],"ko":["Aucun fondement ni évaluation","Montant arbitraire"]}],"concepts":[{"label":"Invoque le droit à indemnité","re":"indemnite","pts":6,"key":true},{"label":"Inclut la valeur du fonds de commerce","re":"valeur du fonds|fonds de commerce|clientele","pts":4},{"label":"Demande une expertise","re":"expert","pts":4}],"articles":[{"code":"L49-16","article":"7","label":"Art. 7 loi 49-16 (indemnité de résiliation)","pts":4}],"faille":"Sans évaluation, la demande d'indemnité est inopérante.","concede":"Le principe de l'indemnité est acquis. Reste à la chiffrer."},{"name":"Le montant et le maintien dans les lieux","adverse":"À titre subsidiaire, la bailleresse propose six mois de loyer.","prompt":"Concluez.","options":[{"label":"Maintien jusqu'au paiement + expertise","detail":"Rejet de l'expulsion ; à défaut, indemnité évaluée par expert avant tout départ.","pts":16,"speech":"Nous concluons à la nullité du congé. À titre subsidiaire, l'indemnité doit être fixée par expertise et versée avant toute libération des lieux. Six mois de loyer ne couvrent ni la valeur du fonds ni les frais de déménagement.","ok":["Conclusions hiérarchisées","Lie le départ au paiement"],"ko":[]},{"label":"Accepter six mois de loyer","detail":"Transiger.","pts":8,"speech":"Le locataire accepte la proposition.","ok":[],"ko":["Bien inférieur à la valeur d'un fonds exploité depuis neuf ans"]}],"concepts":[{"label":"Nullité du congé à titre principal","re":"nul|irregul|principal","pts":4,"key":true},{"label":"Indemnité fixée par expert","re":"expert","pts":4},{"label":"Pas de départ avant paiement","re":"avant|paiement|maintien","pts":3}],"articles":[],"faille":"Le locataire accepte au fond le principe du départ.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le congé n'expose pas de motif précis et ne respecte pas le délai légal ; Par ces motifs : déclare le congé nul et déboute la bailleresse de sa demande d'expulsion."},{"min":45,"text":"Le Tribunal, attendu que le congé est valable en son principe mais que le locataire a droit à une indemnité de résiliation ; Par ces motifs : ordonne une expertise pour évaluer le fonds et subordonne l'éviction au paiement de l'indemnité."},{"min":0,"text":"Le Tribunal, attendu que le locataire ne critique utilement ni le congé ni son motif ; Par ces motifs : valide le congé et alloue une indemnité de six mois de loyer."}]},{"id":"concurrence","matiere":"affaires","title":"Douceurs d'Agadir c/ Sucré Salé SARL","court":"Tribunal de commerce d'Agadir","object":"Concurrence déloyale : imitation d'emballage et dénigrement. Demande de 300 000 DH.","you":"Avocat de la demande (Douceurs d'Agadir)","adverseName":"Avocat de Sucré Salé","facts":"Douceurs d'Agadir vend depuis dix ans des biscuits dans une boîte orange à motifs d'arganier. Sucré Salé a lancé une boîte orange très proche, puis ses commerciaux ont affirmé aux revendeurs que les biscuits de Douceurs d'Agadir « contenaient des huiles de mauvaise qualité ». Les ventes de Douceurs d'Agadir ont baissé de 35 % en six mois.","rounds":[{"name":"Les faits de concurrence déloyale","adverse":"Monsieur le Président, la couleur orange n'appartient à personne. Le commerce est libre et la concurrence aussi.","prompt":"Caractérisez la concurrence déloyale.","options":[{"label":"Confusion + dénigrement","detail":"Imitation créant la confusion et propos dénigrants : deux faits de concurrence déloyale.","pts":18,"speech":"Ce n'est pas la couleur que nous reprochons, mais l'ensemble : même couleur, même motif d'arganier, même format, créant une confusion dans l'esprit de la clientèle. S'y ajoutent des propos dénigrants tenus aux revendeurs, attestés par trois d'entre eux. Ces faits constituent une concurrence déloyale ouvrant droit à dommages-intérêts.","ok":["Raisonne sur l'impression d'ensemble","Ajoute le dénigrement","Produit des attestations"],"ko":[]},{"label":"Revendiquer la couleur","detail":"Soutenir que l'orange est réservé à la demanderesse.","pts":6,"speech":"Notre cliente a l'exclusivité de la couleur orange pour ses biscuits.","ok":[],"ko":["Aucun droit exclusif sur une couleur","Oublie le dénigrement"]}],"concepts":[{"label":"Invoque la confusion / l'imitation","re":"confusion|imitation|ressembl|copi","pts":6,"key":true},{"label":"Invoque le dénigrement","re":"denigr|propos|mauvaise qualite","pts":5},{"label":"Produit des preuves (attestations, photos)","re":"attestation|temoign|photo|constat|preuve","pts":3}],"articles":[{"code":"DOC","article":"84","label":"Art. 84 DOC (concurrence déloyale)","pts":4}],"faille":"La demande ne démontre aucun acte déloyal : seulement une concurrence normale.","concede":"Il y a des ressemblances, nous l'admettons. Mais le préjudice reste à prouver."},{"name":"Le préjudice","adverse":"La baisse des ventes s'explique par la hausse des prix de la demanderesse, pas par ma cliente.","prompt":"Établissez le préjudice et le lien de causalité.","options":[{"label":"Chiffres et chronologie","detail":"Baisse de 35 % coïncidant avec le lancement adverse ; prix inchangés ; expertise comptable.","pts":16,"speech":"Nos prix sont inchangés depuis dix-huit mois, comme le montrent les factures. La baisse de 35 % commence le mois du lancement de la boîte concurrente et se concentre chez les revendeurs démarchés. Nous demandons une expertise comptable pour chiffrer le manque à gagner.","ok":["Neutralise l'explication adverse","Établit la chronologie","Demande une expertise"],"ko":[]},{"label":"Affirmer le préjudice","detail":"Dire que le préjudice est évident.","pts":7,"speech":"Le préjudice est évident.","ok":[],"ko":["Aucune preuve du lien de causalité"]}],"concepts":[{"label":"Prouve la baisse et sa chronologie","re":"35|baisse|chronolog|lancement","pts":5,"key":true},{"label":"Écarte l'explication par les prix","re":"prix (inchanges|stables)|pas augmente","pts":4},{"label":"Demande une expertise comptable","re":"expert","pts":4}],"articles":[{"code":"DOC","article":"98","label":"Art. 98 DOC (étendue des dommages)","pts":3}],"faille":"Faute de lien de causalité, aucune réparation n'est due.","concede":"Le lien est plausible. Le montant reste discutable."},{"name":"Les mesures demandées","adverse":"Ma cliente est prête à modifier sa boîte. Toute condamnation pécuniaire serait excessive.","prompt":"Fixez vos demandes.","options":[{"label":"Cessation + dommages + publication","detail":"Interdiction sous astreinte, dommages évalués par expert, publication du jugement.","pts":16,"speech":"Nous demandons l'interdiction de l'emballage litigieux sous astreinte, des dommages-intérêts fixés après expertise, et la publication du jugement auprès des revendeurs, seul moyen de réparer le dénigrement.","ok":["Mesure de cessation","Réparation du dénigrement par publication"],"ko":[]},{"label":"Accepter la modification seule","detail":"Se contenter de l'engagement adverse.","pts":8,"speech":"Nous prenons acte de l'engagement.","ok":[],"ko":["Aucune réparation du préjudice passé"]}],"concepts":[{"label":"Demande la cessation (astreinte, interdiction)","re":"astreinte|interdi|cessation|retrait","pts":5,"key":true},{"label":"Demande des dommages-intérêts","re":"dommages","pts":3},{"label":"Demande la publication","re":"publicat","pts":3}],"articles":[],"faille":"La demande se contente d'un engagement : le préjudice passé reste sans réparation.","concede":"Les demandes sont précises."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'imitation de l'emballage crée un risque de confusion et que le dénigrement est établi par attestations ; Par ces motifs : interdit l'emballage sous astreinte, ordonne une expertise sur le préjudice et la publication du jugement."},{"min":45,"text":"Le Tribunal, attendu que la confusion est établie mais que le préjudice n'est que partiellement démontré ; Par ces motifs : interdit l'emballage et alloue 60 000 Dirhams de dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu que la demanderesse ne démontre ni confusion ni lien de causalité ; Par ces motifs : rejette la demande."}]},{"id":"gerant-sarl","matiere":"affaires","title":"M. Alaoui c/ M. Bennani, gérant de Logistix SARL","court":"Tribunal de commerce de Casablanca","object":"Action en responsabilité d'un associé contre le gérant pour fautes de gestion.","you":"Avocat de l'associé demandeur (M. Alaoui)","adverseName":"Avocat du gérant","facts":"M. Alaoui détient 40 % de Logistix SARL. Le gérant, M. Bennani, a fait louer par la société, à un prix double du marché, un entrepôt appartenant à son beau-frère, sans autorisation de l'assemblée, et a distribué des dividendes alors que l'exercice était déficitaire.","rounds":[{"name":"La faute du gérant","adverse":"Monsieur le Président, le gérant gère. Ses choix relèvent de son pouvoir de gestion ; le juge n'a pas à contrôler l'opportunité.","prompt":"Caractérisez la responsabilité du gérant.","options":[{"label":"Violations de la loi et fautes de gestion","detail":"Conflit d'intérêts non autorisé, loyer excessif, dividendes fictifs.","pts":18,"speech":"Il ne s'agit pas d'opportunité mais de violations caractérisées : une convention passée avec un proche sans autorisation des associés, à un loyer double du marché, et une distribution de dividendes sans bénéfice distribuable. Les gérants répondent envers la société et les tiers des infractions à la loi, des violations des statuts et de leurs fautes de gestion.","ok":["Distingue faute et opportunité","Identifie trois manquements","Cite le régime de responsabilité"],"ko":[]},{"label":"Reprocher la mauvaise gestion en général","detail":"Critiquer les résultats de la société.","pts":7,"speech":"La société perd de l'argent : le gérant est responsable.","ok":[],"ko":["Des pertes ne suffisent pas à prouver une faute"]}],"concepts":[{"label":"Invoque le conflit d'intérêts / convention non autorisée","re":"beau-frere|conflit|convention|autoris","pts":5,"key":true},{"label":"Invoque le loyer excessif","re":"loyer|double|prix","pts":4},{"label":"Invoque les dividendes fictifs","re":"dividende","pts":5}],"articles":[{"code":"L5-96","article":"67","label":"Art. 67 loi 5-96 (responsabilité des gérants de SARL)","pts":4}],"faille":"L'associé ne démontre aucune faute précise.","concede":"Les faits sont établis. Reste le préjudice."},{"name":"La dimension pénale","adverse":"Les dividendes ont été votés par l'assemblée : le gérant n'a fait qu'exécuter.","prompt":"Répondez.","options":[{"label":"Délit de répartition de dividendes fictifs","detail":"La loi sanctionne pénalement le gérant qui distribue sciemment des dividendes fictifs.","pts":15,"speech":"Le vote de l'assemblée ne couvre pas le gérant : c'est lui qui a présenté des comptes laissant croire à un bénéfice. La loi punit les gérants qui opèrent sciemment entre associés la répartition de dividendes fictifs. Nous nous réservons de saisir le parquet.","ok":["Écarte l'excuse du vote","Mentionne la sanction pénale"],"ko":[]},{"label":"Admettre le vote","detail":"Concéder que l'assemblée a validé.","pts":6,"speech":"Il est exact que l'assemblée a voté.","ok":[],"ko":["Laisse tomber le grief le plus grave"]}],"concepts":[{"label":"Le vote ne couvre pas le gérant","re":"vote|assemblee","pts":4,"key":true},{"label":"Mentionne le délit / la sanction pénale","re":"penal|delit|emprisonnement|parquet|fictif","pts":5}],"articles":[{"code":"L5-96","article":"107","label":"Art. 107 loi 5-96 (dividendes fictifs)","pts":4}],"faille":"Le vote de l'assemblée couvre le gérant.","concede":"La question pénale relève d'une autre juridiction."},{"name":"Les réparations","adverse":"Le gérant propose de baisser le loyer pour l'avenir.","prompt":"Fixez vos demandes.","options":[{"label":"Réparation à la société + révocation","detail":"Restitution du surcoût de loyer, des dividendes, et révocation pour juste motif.","pts":16,"speech":"Nous demandons la condamnation du gérant à verser à la société le surcoût de loyer depuis le début du bail et le montant des dividendes indûment distribués, et sa révocation pour juste motif.","ok":["Réparation au profit de la société","Demande la révocation"],"ko":[]},{"label":"Demander des dommages pour soi","detail":"Réclamer une indemnité personnelle de 40 % des pertes.","pts":9,"speech":"M. Alaoui réclame 40 % des pertes.","ok":[],"ko":["Le préjudice est d'abord celui de la société"]}],"concepts":[{"label":"Réparation au profit de la société","re":"societe","pts":4,"key":true},{"label":"Chiffre le surcoût / les dividendes","re":"surcout|dividende|loyer","pts":4},{"label":"Demande la révocation","re":"revoc","pts":3}],"articles":[],"faille":"La demande vise un préjudice personnel non démontré.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le gérant a conclu sans autorisation une convention défavorable avec un proche et distribué des dividendes fictifs ; Par ces motifs : le condamne à verser à la société le surcoût de loyer et les dividendes indûment distribués, et prononce sa révocation."},{"min":45,"text":"Le Tribunal, attendu que la convention litigieuse constitue une faute de gestion ; Par ces motifs : condamne le gérant à rembourser le surcoût de loyer et rejette le surplus."},{"min":0,"text":"Le Tribunal, attendu qu'aucune faute précise n'est démontrée ; Par ces motifs : rejette la demande."}]},{"id":"retard-paiement","matiere":"affaires","title":"Imprimerie Tétouan c/ Groupe Média Nord","court":"Tribunal de commerce de Tétouan","object":"Indemnité de retard sur des factures payées avec quatre mois de retard.","you":"Avocat du fournisseur (Imprimerie Tétouan)","adverseName":"Avocat de Média Nord","facts":"L'imprimerie a livré des magazines avec paiement convenu à 60 jours. Média Nord a payé les 400 000 DH de factures avec quatre mois de retard. L'imprimerie réclame l'indemnité de retard prévue par le Code de commerce ; Média Nord refuse, aucune pénalité n'étant écrite au contrat.","rounds":[{"name":"L'indemnité est-elle due ?","adverse":"Monsieur le Président, le contrat ne prévoit aucune pénalité de retard. Le principal a été payé : la demande est sans objet.","prompt":"Défendez le principe de l'indemnité de retard.","options":[{"label":"Indemnité légale","detail":"Les conditions de paiement doivent prévoir une indemnité exigible dès le lendemain de l'échéance, à un taux minimal réglementaire.","pts":17,"speech":"Le Code de commerce impose que les conditions de paiement précisent une indemnité de retard exigible le jour suivant la date convenue, à un taux qui ne peut être inférieur au taux réglementaire. L'absence de clause ne prive pas le créancier de ce minimum légal.","ok":["Invoque le régime légal des délais de paiement","Écarte l'argument de l'absence de clause"],"ko":[]},{"label":"Réclamer des dommages généraux","detail":"Demander une indemnisation sans fondement précis.","pts":8,"speech":"Notre cliente a subi un préjudice de trésorerie.","ok":[],"ko":["Ne mobilise pas le régime spécial plus favorable"]}],"concepts":[{"label":"Invoque l'indemnité légale de retard","re":"indemnite de retard|taux|reglementaire","pts":6,"key":true},{"label":"Exigible dès le lendemain de l'échéance","re":"lendemain|jour suivant|echeance","pts":4},{"label":"L'absence de clause est indifférente","re":"clause|contrat","pts":3}],"articles":[{"code":"CCOM","article":"78-3","label":"Art. 78-3 Code de commerce (indemnité de retard)","pts":5}],"faille":"Sans clause ni fondement légal invoqué, aucune pénalité n'est due.","concede":"Le régime légal s'applique, soit. Mais le montant se discute."},{"name":"Le calcul","adverse":"Le retard s'explique par une réorganisation interne ; et le fournisseur a accepté les paiements sans réserve.","prompt":"Répondez sur le calcul et l'acceptation des paiements.","options":[{"label":"Calcul précis, pas de renonciation","detail":"Taux légal appliqué par facture et par jour ; un paiement accepté n'emporte pas renonciation.","pts":16,"speech":"Nous produisons un tableau : pour chaque facture, l'échéance, la date de paiement et l'indemnité au taux réglementaire. Accepter un paiement tardif n'est pas renoncer à l'indemnité, et des difficultés internes ne sont pas une force majeure.","ok":["Produit un calcul par facture","Écarte la renonciation","Écarte la réorganisation interne"],"ko":[]},{"label":"Réclamer un forfait","detail":"Demander 20 % des factures.","pts":6,"speech":"Nous demandons 80 000 Dirhams.","ok":[],"ko":["Aucun calcul","Montant arbitraire"]}],"concepts":[{"label":"Calcul facture par facture","re":"tableau|calcul|facture par facture|par jour","pts":5,"key":true},{"label":"Pas de renonciation","re":"renonc|sans reserve","pts":4},{"label":"La réorganisation n'est pas une force majeure","re":"force majeure|reorganis|interne","pts":3}],"articles":[],"faille":"La demande n'est pas chiffrée sérieusement.","concede":"Le calcul est clair."},{"name":"Conclusions","adverse":"Média Nord propose de régler la moitié pour clore le litige.","prompt":"Concluez.","options":[{"label":"Totalité de l'indemnité légale","detail":"Maintenir le montant calculé, avec dommages pour retard sur l'indemnité.","pts":15,"speech":"Nous maintenons l'indemnité légale telle que calculée. Le minimum fixé par la loi n'a pas vocation à être divisé par deux.","ok":["Cohérent avec le régime légal"],"ko":[]},{"label":"Accepter la moitié","detail":"Transiger.","pts":9,"speech":"Nous acceptons la proposition.","ok":["Rapidité"],"ko":["Renonce à la moitié d'un minimum légal"]}],"concepts":[{"label":"Maintient le calcul légal","re":"maintien|totalite|calcul","pts":4,"key":true}],"articles":[],"faille":"Le fournisseur se contente d'une transaction.","concede":"Nous prenons acte."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'indemnité de retard est due de plein droit au taux minimal réglementaire, nonobstant le silence du contrat ; Par ces motifs : condamne Média Nord au paiement de l'indemnité calculée facture par facture."},{"min":45,"text":"Le Tribunal, attendu que l'indemnité légale est due mais que son calcul doit être vérifié ; Par ces motifs : en fixe le principe et ordonne une expertise comptable."},{"min":0,"text":"Le Tribunal, attendu que le fournisseur n'invoque aucun fondement précis ; Par ces motifs : rejette la demande."}]},{"id":"redressement","matiere":"affaires","title":"Matériaux du Sud c/ syndic de Batiplus SA","court":"Tribunal de commerce d'Agadir","object":"Déclaration de créance tardive dans une procédure de redressement judiciaire.","you":"Avocat du créancier (Matériaux du Sud)","adverseName":"Avocat du syndic","facts":"Batiplus SA a été placée en redressement judiciaire. Matériaux du Sud, à qui elle doit 650 000 DH, figurait sur la liste des créanciers remise par la débitrice, mais n'a jamais reçu l'avis du syndic. Elle a déclaré sa créance trois mois après la publication du jugement d'ouverture. Le syndic la dit forclose.","rounds":[{"name":"La forclusion","adverse":"Monsieur le Président, la déclaration doit intervenir dans les deux mois. Matériaux du Sud a déclaré après trois mois : elle est forclose.","prompt":"Contestez la forclusion.","options":[{"label":"Le délai n'a pas couru","detail":"Pour un créancier inscrit sur la liste, le délai court à compter de l'avis du syndic, jamais reçu.","pts":18,"speech":"Le délai de deux mois ne court pas pour tous à partir de la publication. Pour les créanciers inscrits sur la liste fournie par le débiteur ou connus du syndic, il court à compter de l'avis que le syndic doit leur adresser. Matériaux du Sud figurait sur la liste et n'a jamais reçu cet avis : le délai n'a donc pas commencé à courir.","ok":["Distingue créanciers connus et inconnus","Identifie le point de départ du délai","S'appuie sur l'absence d'avis"],"ko":[]},{"label":"Invoquer l'équité","detail":"Demander la bienveillance du tribunal.","pts":6,"speech":"Il serait injuste de priver ma cliente de sa créance.","ok":[],"ko":["Aucun argument juridique"]}],"concepts":[{"label":"Le délai court à partir de l'avis du syndic","re":"avis","pts":6,"key":true},{"label":"Créancier inscrit sur la liste / connu","re":"liste|connu|inscrit","pts":5},{"label":"Délai de deux mois","re":"deux mois|2 mois","pts":3}],"articles":[{"code":"CCOM","article":"719","label":"Art. 719 Code de commerce (déclaration au syndic)","pts":3},{"code":"CCOM","article":"720","label":"Art. 720 Code de commerce (délai de deux mois)","pts":3}],"faille":"Le créancier ne démontre pas qu'il était connu du syndic.","concede":"L'avis n'a pas été envoyé, c'est exact. Le montant reste à vérifier."},{"name":"La preuve de la créance","adverse":"Subsidiairement, le syndic conteste le montant : certaines factures ne sont pas signées par Batiplus.","prompt":"Justifiez la créance.","options":[{"label":"Pièces commerciales","detail":"Bons de livraison signés, relevés de compte, preuve libre entre commerçants.","pts":16,"speech":"Les livraisons sont attestées par des bons signés par les chefs de chantier de Batiplus et par le relevé de compte que Batiplus elle-même a reconnu en fin d'exercice. Entre commerçants, la preuve est libre.","ok":["Pièces émanant de la débitrice","Liberté de la preuve"],"ko":[]},{"label":"Affirmer le montant","detail":"Maintenir sans pièces.","pts":6,"speech":"Le montant est exact.","ok":[],"ko":["Aucune pièce"]}],"concepts":[{"label":"Bons signés / relevé reconnu","re":"bons?|signe|releve|reconnu","pts":5,"key":true},{"label":"Liberté de la preuve commerciale","re":"liberte de la preuve|preuve (est )?libre","pts":4}],"articles":[{"code":"CCOM","article":"334","label":"Art. 334 Code de commerce (preuve libre)","pts":3}],"faille":"La créance n'est pas justifiée.","concede":"Les pièces sont probantes."},{"name":"Conclusions","adverse":"Le syndic demande que la créance soit au moins réduite de 20 %.","prompt":"Concluez.","options":[{"label":"Admission intégrale","detail":"Déclaration recevable, créance admise pour 650 000 DH.","pts":15,"speech":"Nous demandons que la déclaration soit jugée recevable et la créance admise au passif pour 650 000 Dirhams.","ok":["Conclusion nette"],"ko":[]},{"label":"Accepter la réduction","detail":"Transiger à 520 000 DH.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Abandonne 130 000 DH sans motif"]}],"concepts":[{"label":"Recevabilité et admission","re":"recevab|admi","pts":4,"key":true}],"articles":[],"faille":"Le créancier n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le créancier figurait sur la liste fournie par la débitrice et n'a pas reçu l'avis du syndic, de sorte que le délai de déclaration n'a pas couru ; Par ces motifs : déclare la déclaration recevable et admet la créance pour 650 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu que la déclaration est recevable mais que certaines factures ne sont pas justifiées ; Par ces motifs : admet la créance pour 540 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la déclaration est intervenue hors délai sans justification ; Par ces motifs : constate la forclusion."}]},{"id":"clause-abusive","matiere":"affaires","title":"Mme Tazi c/ Fitness Club Royal","court":"Tribunal de première instance de Rabat","object":"Clause abusive dans un abonnement de salle de sport.","you":"Avocat de la consommatrice (Mme Tazi)","adverseName":"Avocat du club","facts":"Mme Tazi a souscrit un abonnement de 24 mois. Le contrat prévoit qu'en cas de résiliation, même pour raison médicale, la totalité des mensualités restantes est due, alors que le club peut modifier ses horaires et fermer des activités sans préavis. Après une opération, Mme Tazi veut résilier.","rounds":[{"name":"Le caractère abusif","adverse":"Monsieur le Président, Mme Tazi a signé en connaissance de cause. Le contrat fait la loi des parties.","prompt":"Démontrez le caractère abusif de la clause.","options":[{"label":"Déséquilibre significatif","detail":"Clause qui crée un déséquilibre significatif entre les droits et obligations des parties, au détriment de la consommatrice.","pts":18,"speech":"La force obligatoire du contrat cède devant la protection du consommateur : est abusive toute clause qui crée, à son détriment, un déséquilibre significatif entre les droits et obligations des parties. Ici, la cliente doit tout payer même si elle ne peut plus venir pour raison médicale, tandis que le club peut réduire unilatéralement ses prestations sans préavis.","ok":["Invoque le régime spécial des clauses abusives","Démontre le déséquilibre par comparaison"],"ko":[]},{"label":"Invoquer la maladie seule","detail":"Demander une exception compassionnelle.","pts":8,"speech":"Mme Tazi est malade, elle ne peut pas payer.","ok":[],"ko":["Ne qualifie pas la clause"]}],"concepts":[{"label":"Déséquilibre significatif","re":"desequilibre","pts":6,"key":true},{"label":"Compare les droits du club et de la cliente","re":"club peut|modifier|horaires|unilateral","pts":4},{"label":"Relève la raison médicale","re":"medical|operation|sante","pts":3}],"articles":[{"code":"L31-08","article":"15","label":"Art. 15 loi 31-08 (définition de la clause abusive)","pts":5}],"faille":"La consommatrice ne démontre aucun déséquilibre.","concede":"Le déséquilibre est réel. Mais le contrat doit-il tomber entier ?"},{"name":"La sanction","adverse":"Si la clause tombe, tout le contrat tombe : Mme Tazi devra rembourser les séances utilisées à plein tarif.","prompt":"Précisez la sanction.","options":[{"label":"Nullité de la clause seule","detail":"La clause abusive est nulle ; le contrat subsiste dans ses autres dispositions.","pts":17,"speech":"La loi est précise : la clause abusive est nulle et de nul effet, mais le contrat reste applicable dans ses autres dispositions s'il peut subsister sans elle. La cliente a payé les mois écoulés ; seule la clause de pénalité disparaît.","ok":["Distingue nullité de la clause et du contrat"],"ko":[]},{"label":"Demander l'annulation totale","detail":"Faire annuler tout le contrat.","pts":7,"speech":"Nous demandons l'annulation du contrat entier.","ok":[],"ko":["Expose la cliente à des restitutions"]}],"concepts":[{"label":"Nullité de la seule clause","re":"clause.*nul|nul.*clause|nulle et de nul effet","pts":6,"key":true},{"label":"Le contrat subsiste","re":"subsist|reste applicable|autres dispositions","pts":4}],"articles":[{"code":"L31-08","article":"19","label":"Art. 19 loi 31-08 (nullité des clauses abusives)","pts":4}],"faille":"La demande d'annulation totale se retourne contre la consommatrice.","concede":"La nullité partielle s'impose."},{"name":"Conclusions","adverse":"Le club propose de suspendre l'abonnement trois mois au lieu de le résilier.","prompt":"Concluez.","options":[{"label":"Résiliation sans pénalité","detail":"Nullité de la clause, résiliation au jour de la demande, remboursement des prélèvements postérieurs.","pts":16,"speech":"Nous demandons la nullité de la clause, la résiliation à la date de la demande et le remboursement des prélèvements effectués depuis.","ok":["Demandes précises"],"ko":[]},{"label":"Accepter la suspension","detail":"Accepter trois mois de suspension.","pts":8,"speech":"Mme Tazi accepte.","ok":[],"ko":["La clause abusive reste en place"]}],"concepts":[{"label":"Résiliation et remboursement","re":"resili|rembours","pts":4,"key":true}],"articles":[],"faille":"La consommatrice ne précise pas ce qu'elle demande.","concede":"Les demandes sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la clause imposant le paiement de toutes les mensualités restantes, même pour motif médical, crée un déséquilibre significatif au détriment de la consommatrice ; Par ces motifs : la déclare nulle, constate la résiliation et ordonne le remboursement des prélèvements postérieurs."},{"min":45,"text":"Le Tribunal, attendu que la clause est abusive ; Par ces motifs : la déclare nulle et réduit les sommes dues à deux mensualités."},{"min":0,"text":"Le Tribunal, attendu que la consommatrice ne démontre pas le caractère abusif ; Par ces motifs : rejette la demande."}]},{"id":"degat-eaux","matiere":"civil","title":"M. Kettani c/ M. Rami","court":"Tribunal de première instance de Meknès","object":"Dégât des eaux provenant de l'appartement du dessus : 45 000 DH de dommages.","you":"Avocat de la victime (M. Kettani)","adverseName":"Avocat de M. Rami","facts":"Une conduite du chauffe-eau de M. Rami, au troisième étage, a cédé pendant son absence. L'eau a endommagé le plafond, le parquet et un ordinateur de M. Kettani, au deuxième étage. Un constat d'huissier et un devis de 45 000 DH ont été établis.","rounds":[{"name":"Le fondement de la responsabilité","adverse":"Monsieur le Président, mon client était absent et n'a commis aucune faute. Une fuite est un accident.","prompt":"Fondez la responsabilité.","options":[{"label":"Responsabilité du fait des choses","detail":"Le gardien répond du dommage causé par la chose qu'il a sous sa garde, sans qu'il faille prouver sa faute.","pts":18,"speech":"Nous n'avons pas à prouver une faute. Chacun répond du dommage causé par les choses qu'il a sous sa garde ; le chauffe-eau et ses conduites sont sous la garde de M. Rami, et ils sont la cause directe du dommage. Pour s'exonérer, c'est à lui de démontrer qu'il a tout fait pour empêcher le dommage et que celui-ci vient d'un cas fortuit ou de la faute de la victime.","ok":["Choisit le bon fondement","Renverse la charge de la preuve"],"ko":[]},{"label":"Chercher une faute","detail":"Soutenir que M. Rami a mal entretenu son chauffe-eau, sans preuve.","pts":9,"speech":"M. Rami n'entretenait pas son chauffe-eau.","ok":["Piste possible"],"ko":["Faute à prouver, alors qu'un fondement plus simple existe"]}],"concepts":[{"label":"Invoque la garde de la chose","re":"garde|chose","pts":6,"key":true},{"label":"Pas besoin de prouver une faute","re":"sans faute|pas (a|besoin de) prouver|presum","pts":4},{"label":"Lien de causalité (cause directe)","re":"cause directe|causalite|constat","pts":3}],"articles":[{"code":"DOC","article":"88","label":"Art. 88 DOC (responsabilité du fait des choses)","pts":5}],"faille":"La victime ne prouve aucune faute : la demande doit être rejetée.","concede":"Le fondement est le bon. Reste l'exonération."},{"name":"L'exonération","adverse":"Le chauffe-eau avait été révisé six mois plus tôt par un professionnel : mon client a fait tout ce qui était nécessaire.","prompt":"Répondez à la tentative d'exonération.","options":[{"label":"Les deux conditions sont cumulatives","detail":"Il faut avoir tout fait pour empêcher le dommage ET que le dommage dépende d'un cas fortuit ou de la faute de la victime.","pts":16,"speech":"L'exonération exige deux conditions cumulatives : avoir fait tout le nécessaire, et que le dommage dépende d'un cas fortuit, d'une force majeure ou de la faute de la victime. Une révision six mois plus tôt ne prouve aucun cas fortuit : une conduite qui cède est un défaut de la chose elle-même.","ok":["Rappelle le caractère cumulatif","Le défaut de la chose n'est pas un cas fortuit"],"ko":[]},{"label":"Contester la révision","detail":"Douter de la facture de révision.","pts":7,"speech":"La facture de révision est peut-être fausse.","ok":[],"ko":["Accusation sans preuve"]}],"concepts":[{"label":"Conditions cumulatives","re":"cumulat|deux conditions|et que","pts":5,"key":true},{"label":"Pas de cas fortuit / force majeure","re":"cas fortuit|force majeure","pts":5}],"articles":[],"faille":"La révision prouve la diligence du gardien : il est exonéré.","concede":"La révision ne suffit pas. Le montant reste à discuter."},{"name":"Le montant","adverse":"Le devis est surévalué : le parquet était ancien et l'ordinateur avait cinq ans.","prompt":"Défendez l'évaluation du préjudice.","options":[{"label":"Perte effective et dépenses de remise en état","detail":"Constat, devis, facture de l'ordinateur ; demande d'expertise en cas de contestation.","pts":15,"speech":"La réparation couvre la perte effective et les dépenses nécessaires pour réparer les suites du fait dommageable. Le constat et le devis sont détaillés. Si la défense conteste la vétusté, qu'une expertise la chiffre ; elle ne peut pas l'affirmer sans preuve.","ok":["Notion de perte effective","Propose une expertise"],"ko":[]},{"label":"Ajouter un préjudice moral élevé","detail":"Réclamer 100 000 DH de préjudice moral.","pts":7,"speech":"Nous ajoutons 100 000 Dirhams de préjudice moral.","ok":[],"ko":["Demande disproportionnée"]}],"concepts":[{"label":"Perte effective / dépenses de remise en état","re":"perte|depenses|remise en etat|devis","pts":5,"key":true},{"label":"Demande une expertise","re":"expert","pts":4}],"articles":[{"code":"DOC","article":"98","label":"Art. 98 DOC (étendue des dommages)","pts":3}],"faille":"Le préjudice est surévalué.","concede":"Le montant sera ajusté pour vétusté."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le dommage a pour cause directe une chose sous la garde du défendeur, qui ne prouve ni cas fortuit ni faute de la victime ; Par ces motifs : le condamne à payer 45 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu que la responsabilité du gardien est engagée, mais qu'il convient de tenir compte de la vétusté ; Par ces motifs : le condamne à payer 32 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la victime ne précise pas le fondement de sa demande ni n'établit de faute ; Par ces motifs : rejette la demande."}]},{"id":"mur-effondre","matiere":"civil","title":"Mme Berrada c/ M. Lahlou","court":"Tribunal de première instance de Fès","object":"Effondrement du mur d'une maison ancienne sur une voiture garée.","you":"Avocat du propriétaire (M. Lahlou)","adverseName":"Avocat de Mme Berrada","facts":"Le mur de clôture de la maison de M. Lahlou, à la médina, s'est effondré pendant un orage exceptionnel, écrasant la voiture de Mme Berrada. La météo nationale avait émis une alerte rouge ; plusieurs constructions récentes du quartier ont aussi été endommagées. Un rapport d'entretien de l'an dernier décrit le mur comme sain.","rounds":[{"name":"Le régime applicable","adverse":"Monsieur le Président, le propriétaire d'un édifice répond de son écroulement. M. Lahlou doit payer.","prompt":"Présentez la défense.","options":[{"label":"Ruine due à un événement extérieur","detail":"Le propriétaire répond de la ruine due à la vétusté, au défaut d'entretien ou au vice de construction ; ce n'est pas le cas.","pts":17,"speech":"La responsabilité du propriétaire d'un édifice suppose que l'écroulement soit arrivé par vétusté, défaut d'entretien ou vice de construction. Or le rapport d'entretien de l'an dernier décrit un mur sain, et l'effondrement est survenu lors d'un orage sous alerte rouge qui a aussi endommagé des constructions récentes.","ok":["Rappelle les causes légales de la responsabilité","Produit le rapport d'entretien","Met en avant l'événement exceptionnel"],"ko":[]},{"label":"Nier être propriétaire","detail":"Soutenir que le mur est mitoyen.","pts":5,"speech":"Ce mur n'est pas à mon client.","ok":[],"ko":["Contredit le dossier"]}],"concepts":[{"label":"Pas de vétusté, défaut d'entretien ni vice","re":"vetuste|entretien|vice","pts":6,"key":true},{"label":"Événement exceptionnel / orage / alerte","re":"orage|alerte|exceptionnel|force majeure","pts":5},{"label":"Produit le rapport d'entretien","re":"rapport|sain","pts":3}],"articles":[{"code":"DOC","article":"89","label":"Art. 89 DOC (responsabilité du propriétaire d'un édifice)","pts":4}],"faille":"Le propriétaire ne démontre pas l'origine extérieure de l'effondrement.","concede":"L'orage était exceptionnel. Mais il reste la garde de la chose."},{"name":"La garde de la chose","adverse":"À défaut, le propriétaire est gardien du mur et répond du fait des choses.","prompt":"Répondez.","options":[{"label":"Exonération : diligence + force majeure","detail":"Le gardien s'exonère s'il a fait le nécessaire et si le dommage dépend d'une force majeure.","pts":16,"speech":"Même sur ce terrain, M. Lahlou s'exonère : il a fait tout le nécessaire, comme le prouve l'entretien régulier, et le dommage dépend d'une force majeure, un orage sous alerte rouge qui a frappé tout le quartier.","ok":["Réunit les deux conditions d'exonération"],"ko":[]},{"label":"Ignorer","detail":"Ne pas répondre à ce fondement.","pts":5,"speech":"Nous maintenons notre position.","ok":[],"ko":["Laisse le second fondement sans réponse"]}],"concepts":[{"label":"A fait le nécessaire (entretien)","re":"necessaire|entretien|diligen","pts":5,"key":true},{"label":"Force majeure","re":"force majeure|orage|alerte","pts":5}],"articles":[{"code":"DOC","article":"88","label":"Art. 88 DOC (fait des choses et exonération)","pts":3}],"faille":"Le gardien ne s'exonère pas.","concede":"Les conditions d'exonération sont plausibles."},{"name":"Conclusions","adverse":"Mme Berrada demande au moins la moitié des réparations, soit 30 000 DH.","prompt":"Concluez.","options":[{"label":"Rejet, subsidiairement expertise","detail":"Rejet total ; à titre subsidiaire, expertise sur la cause de l'effondrement.","pts":15,"speech":"Nous concluons au rejet. À titre subsidiaire, une expertise sur la cause de l'effondrement permettra de vérifier qu'aucun défaut d'entretien n'est en cause.","ok":["Hiérarchise les demandes"],"ko":[]},{"label":"Accepter 30 000 DH","detail":"Transiger.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Reconnaît une responsabilité contestable"]}],"concepts":[{"label":"Rejet / expertise","re":"rejet|expert","pts":4,"key":true}],"articles":[],"faille":"Le propriétaire n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'écroulement n'est dû ni à la vétusté ni à un défaut d'entretien, mais à un orage exceptionnel constitutif de force majeure ; Par ces motifs : rejette la demande."},{"min":45,"text":"Le Tribunal, attendu que la cause de l'effondrement doit être précisée ; Par ces motifs : ordonne une expertise."},{"min":0,"text":"Le Tribunal, attendu que le propriétaire ne démontre pas l'origine extérieure de l'effondrement ; Par ces motifs : le condamne à réparer l'intégralité du dommage."}]},{"id":"vice-cache","matiere":"civil","title":"M. Ouazzani c/ M. Chraibi","court":"Tribunal de première instance de Kénitra","object":"Voiture d'occasion : boîte de vitesses défaillante découverte après la vente.","you":"Avocat de l'acheteur (M. Ouazzani)","adverseName":"Avocat du vendeur","facts":"M. Ouazzani a acheté à un particulier une voiture d'occasion 95 000 DH. Douze jours après la livraison, la boîte de vitesses a lâché ; le garagiste a constaté une fuite ancienne colmatée avec un produit masquant. M. Ouazzani a adressé une réclamation écrite le jour même et assigné vingt jours après la livraison.","rounds":[{"name":"Le vice","adverse":"Monsieur le Président, une voiture d'occasion s'achète en l'état. L'acheteur aurait dû la faire inspecter.","prompt":"Caractérisez le vice.","options":[{"label":"Vice caché qui rend la chose impropre","detail":"Le vendeur garantit les vices qui rendent la chose impropre à son usage ; ici le défaut était masqué.","pts":17,"speech":"Le vendeur garantit les vices qui diminuent sensiblement la valeur de la chose ou la rendent impropre à l'usage auquel elle est destinée. Une boîte de vitesses hors d'usage rend la voiture impropre à rouler, et la fuite avait été colmatée avec un produit masquant : le vice n'était pas décelable par un acheteur non professionnel.","ok":["Qualifie le vice","Démontre son caractère caché","Met en évidence la dissimulation"],"ko":[]},{"label":"Invoquer la déception","detail":"Dire que la voiture ne plaît plus.","pts":4,"speech":"Mon client est déçu de son achat.","ok":[],"ko":["Aucun vice juridiquement caractérisé"]}],"concepts":[{"label":"Rend la chose impropre à l'usage / diminue sa valeur","re":"impropre|usage|valeur","pts":5,"key":true},{"label":"Vice caché / non décelable","re":"cache|masqu|decelable|colmat","pts":5},{"label":"Rapport du garagiste","re":"garag|rapport|constat","pts":3}],"articles":[{"code":"DOC","article":"549","label":"Art. 549 DOC (garantie des vices)","pts":5}],"faille":"L'acheteur ne démontre pas un vice antérieur à la vente.","concede":"Le vice est établi. Mais l'action est-elle dans les délais ?"},{"name":"Le délai d'action","adverse":"L'action est tardive : pour un meuble, le délai est très court.","prompt":"Répondez sur le délai.","options":[{"label":"Action dans les trente jours","detail":"Pour une chose mobilière, l'action doit être intentée dans les trente jours après la délivrance : c'est le cas.","pts":17,"speech":"Pour les choses mobilières, l'action doit être intentée dans les trente jours après la délivrance. Le vice est apparu au douzième jour, la réclamation a été faite le jour même et l'assignation au vingtième jour : le délai est respecté.","ok":["Identifie le bon délai","Démontre le respect par les dates"],"ko":[]},{"label":"Dire que le délai ne s'applique pas","detail":"Soutenir qu'aucun délai n'existe.","pts":5,"speech":"Il n'y a aucun délai en la matière.","ok":[],"ko":["Faux : un délai de déchéance existe"]}],"concepts":[{"label":"Trente jours pour un meuble","re":"trente|30 jours","pts":6,"key":true},{"label":"Démontre par les dates","re":"douze|vingt|20 jours|12 jours|delivrance","pts":4}],"articles":[{"code":"DOC","article":"573","label":"Art. 573 DOC (délai de l'action rédhibitoire)","pts":5}],"faille":"L'action est tardive.","concede":"Le délai est respecté. Reste la sanction."},{"name":"La sanction","adverse":"Le vendeur propose de payer la réparation de la boîte, 18 000 DH.","prompt":"Concluez.","options":[{"label":"Résolution et restitution, ou réduction","detail":"Résolution de la vente et restitution du prix ; dommages en raison de la dissimulation.","pts":15,"speech":"Nous demandons la résolution de la vente et la restitution des 95 000 Dirhams contre retour du véhicule, ainsi que des dommages-intérêts : le vendeur, qui a masqué le défaut, ne pouvait l'ignorer. À titre subsidiaire, la prise en charge de la réparation et des frais.","ok":["Demande principale et subsidiaire","Exploite la mauvaise foi du vendeur"],"ko":[]},{"label":"Accepter 18 000 DH","detail":"Transiger.","pts":9,"speech":"Nous acceptons la réparation.","ok":["Rapide"],"ko":["Renonce aux dommages liés à la dissimulation"]}],"concepts":[{"label":"Résolution / restitution du prix","re":"resolution|restitution|95","pts":4,"key":true},{"label":"Mauvaise foi / dissimulation","re":"mauvaise foi|dissimul|masqu","pts":3}],"articles":[],"faille":"L'acheteur ne précise pas sa demande.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la voiture était affectée d'un vice caché la rendant impropre à l'usage, dissimulé par le vendeur, et que l'action a été intentée dans les trente jours ; Par ces motifs : prononce la résolution, ordonne la restitution de 95 000 Dirhams et alloue 10 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que le vice est établi ; Par ces motifs : condamne le vendeur à prendre en charge la réparation, soit 18 000 Dirhams, et les frais d'immobilisation."},{"min":0,"text":"Le Tribunal, attendu que l'acheteur ne démontre pas un vice antérieur à la vente ; Par ces motifs : rejette la demande."}]},{"id":"pret-oral","matiere":"civil","title":"M. Hajji c/ M. Sefrioui","court":"Tribunal de première instance de Oujda","object":"Remboursement d'un prêt de 60 000 DH prétendument consenti sans écrit.","you":"Avocat du défendeur (M. Sefrioui)","adverseName":"Avocat de M. Hajji","facts":"M. Hajji affirme avoir prêté 60 000 DH en espèces à son ancien associé, M. Sefrioui, et produit deux témoins qui disent avoir assisté à la remise de l'argent. Aucun écrit n'a été signé. M. Sefrioui conteste tout prêt.","rounds":[{"name":"La preuve du prêt","adverse":"Monsieur le Président, deux témoins honorables ont vu la remise des fonds. Le prêt est prouvé.","prompt":"Contestez le mode de preuve.","options":[{"label":"Écrit obligatoire au-delà de 10 000 DH","detail":"Les conventions excédant dix mille dirhams ne peuvent être prouvées par témoins.","pts":18,"speech":"La loi exige un écrit : les conventions excédant la valeur de dix mille dirhams ne peuvent être prouvées par témoins. Le prêt allégué est de soixante mille dirhams ; les témoignages sont donc irrecevables pour en établir l'existence.","ok":["Identifie la règle de preuve","Applique le seuil au montant"],"ko":[]},{"label":"Attaquer les témoins","detail":"Mettre en cause l'honnêteté des témoins.","pts":8,"speech":"Ces témoins sont des amis du demandeur.","ok":["Peut affaiblir les témoignages"],"ko":["Passe à côté de l'irrecevabilité"]}],"concepts":[{"label":"Seuil de dix mille dirhams / écrit exigé","re":"dix mille|10 000|10000|ecrit","pts":6,"key":true},{"label":"Témoins irrecevables","re":"temoin","pts":4}],"articles":[{"code":"DOC","article":"443","label":"Art. 443 DOC (preuve par écrit au-delà de 10 000 DH)","pts":5}],"faille":"La défense ne conteste pas sérieusement les témoignages.","concede":"La preuve testimoniale est discutable. Mais il existe d'autres indices."},{"name":"Les autres indices","adverse":"Le demandeur produit aussi un SMS où M. Sefrioui écrit « je te rendrai tout dès que possible ».","prompt":"Répondez à cette nouvelle pièce.","options":[{"label":"Message ambigu, charge de la preuve","detail":"Le SMS ne mentionne ni prêt ni montant ; la preuve incombe au demandeur.","pts":15,"speech":"Ce message ne mentionne ni prêt, ni somme, ni date ; il peut se rapporter au règlement des comptes entre anciens associés. La preuve de l'obligation incombe à celui qui s'en prévaut, et ce message ne suffit pas à l'établir pour soixante mille dirhams.","ok":["Souligne l'ambiguïté","Rappelle la charge de la preuve"],"ko":[]},{"label":"Nier le message","detail":"Dire que le téléphone a été piraté.","pts":5,"speech":"Ce message n'est pas de mon client.","ok":[],"ko":["Affirmation invraisemblable sans preuve"]}],"concepts":[{"label":"Message ambigu (ni prêt ni montant)","re":"ambigu|ni pret|ni montant|ni somme","pts":5,"key":true},{"label":"Charge de la preuve sur le demandeur","re":"preuve|incombe","pts":4}],"articles":[{"code":"DOC","article":"399","label":"Art. 399 DOC (charge de la preuve)","pts":4}],"faille":"Le message vaut reconnaissance de dette.","concede":"Le message est un indice, rien de plus."},{"name":"Conclusions","adverse":"Le demandeur propose un serment décisoire.","prompt":"Concluez.","options":[{"label":"Rejet faute de preuve écrite","detail":"Rejet de la demande ; prudence sur le serment.","pts":14,"speech":"Nous concluons au rejet de la demande, faute de preuve écrite d'un prêt supérieur à dix mille dirhams.","ok":["Conclusion conforme à la règle"],"ko":[]},{"label":"Reconnaître une partie","detail":"Proposer 20 000 DH.","pts":7,"speech":"Mon client propose 20 000 Dirhams.","ok":[],"ko":["Reconnaissance implicite d'un prêt contesté"]}],"concepts":[{"label":"Rejet faute d'écrit","re":"rejet|ecrit","pts":4,"key":true}],"articles":[],"faille":"La défense n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le prêt allégué excède dix mille dirhams et ne peut être prouvé par témoins, et que le message produit ne mentionne ni prêt ni montant ; Par ces motifs : rejette la demande."},{"min":45,"text":"Le Tribunal, attendu que le message constitue un commencement de preuve insuffisant ; Par ces motifs : rejette la demande en l'état."},{"min":0,"text":"Le Tribunal, attendu que le prêt est établi par les témoignages et le message de reconnaissance ; Par ces motifs : condamne le défendeur à payer 60 000 Dirhams."}]},{"id":"loyers-impayes","matiere":"civil","title":"Mme Sqalli c/ M. Daoudi","court":"Tribunal de première instance de Rabat","object":"Loyers d'habitation impayés depuis sept ans et demi.","you":"Avocat de la bailleresse (Mme Sqalli)","adverseName":"Avocat du locataire","facts":"M. Daoudi loue un appartement à Mme Sqalli. Il a cessé de payer régulièrement il y a sept ans et demi, réglant parfois quelques mois. Mme Sqalli réclame 270 000 DH d'arriérés et la résiliation du bail.","rounds":[{"name":"La prescription des loyers","adverse":"Monsieur le Président, les loyers se prescrivent : une grande partie de la demande est irrecevable.","prompt":"Répondez sur la prescription.","options":[{"label":"Limiter loyalement aux cinq dernières années","detail":"Les loyers se prescrivent par cinq ans à compter de chaque échéance : réclamer les loyers non prescrits.","pts":17,"speech":"Il est exact que les loyers se prescrivent par cinq années à partir de l'échéance de chaque terme. Nous limitons donc notre demande aux loyers échus depuis moins de cinq ans, soit 180 000 Dirhams, en produisant le décompte terme par terme.","ok":["Reconnaît la règle de prescription","Recalcule la demande","Produit un décompte"],"ko":[]},{"label":"Invoquer la prescription de quinze ans","detail":"Soutenir que toutes les actions se prescrivent par quinze ans.","pts":6,"speech":"La prescription de droit commun est de quinze ans.","ok":[],"ko":["Ignore la règle spéciale des loyers"]}],"concepts":[{"label":"Cinq ans pour les loyers","re":"cinq ans|5 ans|cinq annees","pts":6,"key":true},{"label":"À partir de chaque échéance / décompte","re":"echeance|terme|decompte","pts":4}],"articles":[{"code":"DOC","article":"391","label":"Art. 391 DOC (prescription quinquennale des loyers)","pts":5}],"faille":"La bailleresse maintient une demande en partie prescrite.","concede":"La demande est recalculée correctement."},{"name":"Les manquements du locataire","adverse":"Le locataire a payé quelques mois chaque année ; il n'a jamais été mis en demeure.","prompt":"Démontrez le manquement.","options":[{"label":"Obligation principale de payer le prix","detail":"Payer le loyer est l'obligation principale du preneur ; les paiements partiels ne la remplissent pas.","pts":15,"speech":"Le preneur est tenu de deux obligations principales, dont celle de payer le prix du louage. Des paiements sporadiques ne la remplissent pas. Au surplus, nous produisons deux lettres recommandées réclamant les arriérés.","ok":["Cite l'obligation principale du preneur","Produit les réclamations écrites"],"ko":[]},{"label":"Insister sur la mauvaise foi","detail":"Accuser le locataire sans pièces.","pts":7,"speech":"Le locataire est de mauvaise foi.","ok":[],"ko":["Aucune pièce"]}],"concepts":[{"label":"Obligation de payer le loyer","re":"payer|prix du louage|obligation","pts":5,"key":true},{"label":"Réclamations / mise en demeure","re":"recommande|reclam|mise en demeure","pts":4}],"articles":[{"code":"DOC","article":"663","label":"Art. 663 DOC (obligations du preneur)","pts":4}],"faille":"La bailleresse ne prouve aucune réclamation.","concede":"Le manquement est établi."},{"name":"Conclusions","adverse":"Le locataire demande un échéancier de cinq ans.","prompt":"Concluez.","options":[{"label":"Paiement + résiliation, échéancier court","detail":"Condamnation aux loyers non prescrits, résiliation, échéancier limité si nécessaire.","pts":15,"speech":"Nous demandons la condamnation au paiement de 180 000 Dirhams, la résiliation du bail et l'expulsion ; un échéancier ne saurait excéder quelques mois après sept ans d'impayés.","ok":["Demandes complètes"],"ko":[]},{"label":"Accepter cinq ans","detail":"Accepter l'échéancier.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Laisse le locataire dans les lieux sans garantie"]}],"concepts":[{"label":"Paiement et résiliation","re":"resili|expuls|paiement","pts":4,"key":true}],"articles":[],"faille":"La bailleresse n'a pas de conclusion claire.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les loyers se prescrivent par cinq ans et que le manquement du preneur à son obligation principale est établi ; Par ces motifs : le condamne à payer 180 000 Dirhams, prononce la résiliation du bail et ordonne l'expulsion."},{"min":45,"text":"Le Tribunal, attendu que les loyers non prescrits sont dus ; Par ces motifs : condamne le locataire à payer 180 000 Dirhams avec un échéancier de douze mois."},{"min":0,"text":"Le Tribunal, attendu qu'une partie de la demande est prescrite et que la bailleresse ne distingue pas ; Par ces motifs : renvoie l'affaire pour production d'un décompte."}]},{"id":"prescription-facture","matiere":"civil","title":"Électro Plus c/ M. Naciri","court":"Tribunal de première instance de Settat","object":"Facture de fournitures impayée depuis six ans.","you":"Avocat du client (M. Naciri)","adverseName":"Avocat d'Électro Plus","facts":"Électro Plus réclame à M. Naciri, particulier, le paiement d'une facture de 38 000 DH pour l'équipement électroménager de sa maison, livré il y a six ans. Aucune relance écrite n'a été envoyée depuis la livraison. M. Naciri affirme avoir payé en espèces mais a perdu le reçu.","rounds":[{"name":"La prescription","adverse":"Monsieur le Président, toutes les actions naissant d'une obligation se prescrivent par quinze ans. La demande est recevable.","prompt":"Opposez la prescription.","options":[{"label":"Prescription de deux ans (fournitures domestiques)","detail":"L'action des marchands pour les fournitures faites aux particuliers pour leurs usages domestiques se prescrit par deux ans.","pts":18,"speech":"Le délai de quinze ans est le droit commun, mais la loi prévoit des exceptions. L'action des marchands et fournisseurs à raison des fournitures faites aux particuliers pour leurs usages domestiques se prescrit par deux ans, à partir du jour de la fourniture. L'électroménager de la maison a été livré il y a six ans, sans aucun acte interruptif : l'action est prescrite depuis longtemps.","ok":["Distingue droit commun et exception","Choisit le délai des fournitures domestiques (deux ans)","Relève l'absence d'acte interruptif"],"ko":[]},{"label":"Prescription de cinq ans","detail":"Invoquer la prescription de cinq ans des fournisseurs.","pts":11,"speech":"L'action des fournisseurs se prescrit par cinq ans ; la livraison date de six ans : l'action est prescrite.","ok":["Le résultat est le même ici"],"ko":["Le délai de cinq ans vise les fournitures entre commerçants, pas celles faites aux particuliers"]}],"concepts":[{"label":"Prescription de deux ans (usages domestiques)","re":"deux ans|2 ans|domestique|particulier","pts":6,"key":true},{"label":"Le droit commun de quinze ans ne s'applique pas","re":"quinze|15 ans|exception","pts":4},{"label":"Aucun acte interruptif","re":"interrupt|relance|aucune","pts":4}],"articles":[{"code":"DOC","article":"388","label":"Art. 388 DOC (prescriptions de cinq ans, deux ans et un an)","pts":4},{"code":"DOC","article":"387","label":"Art. 387 DOC (prescription de droit commun)","pts":2}],"faille":"Le client n'oppose pas utilement la prescription.","concede":"Le délai de deux ans est largement dépassé. Le fournisseur invoque une reconnaissance."},{"name":"La reconnaissance de dette","adverse":"M. Naciri aurait reconnu la dette au téléphone il y a deux ans, ce qui a interrompu la prescription.","prompt":"Répondez.","options":[{"label":"Exiger la preuve de l'interruption","detail":"La preuve de l'interruption incombe à celui qui s'en prévaut ; un appel non prouvé ne suffit pas.","pts":15,"speech":"C'est à Électro Plus de prouver l'acte interruptif qu'elle invoque. Elle ne produit ni écrit, ni enregistrement, ni témoin. Une conversation alléguée ne suffit pas à interrompre la prescription.","ok":["Rappelle la charge de la preuve","Relève l'absence de pièce"],"ko":[]},{"label":"Reconnaître l'appel","detail":"Admettre la conversation.","pts":5,"speech":"Mon client a pu évoquer la facture.","ok":[],"ko":["Fournit à l'adversaire l'interruption"]}],"concepts":[{"label":"Preuve de l'interruption à la charge du fournisseur","re":"preuve|incombe|prouv","pts":5,"key":true},{"label":"Aucune pièce","re":"aucun|ni ecrit|enregistrement","pts":3}],"articles":[{"code":"DOC","article":"399","label":"Art. 399 DOC (charge de la preuve)","pts":3}],"faille":"La reconnaissance téléphonique est vraisemblable.","concede":"L'interruption n'est pas prouvée."},{"name":"Conclusions","adverse":"Le fournisseur demande, à défaut, la moitié de la facture.","prompt":"Concluez.","options":[{"label":"Irrecevabilité pour prescription","detail":"Action prescrite, rejet intégral.","pts":14,"speech":"Nous concluons à l'irrecevabilité de l'action, prescrite.","ok":["Conclusion nette"],"ko":[]},{"label":"Accepter la moitié","detail":"Transiger.","pts":7,"speech":"Mon client accepte.","ok":[],"ko":["Paie une dette prescrite"]}],"concepts":[{"label":"Prescription / irrecevabilité","re":"prescri|irrecevab","pts":4,"key":true}],"articles":[],"faille":"Le client n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'action du fournisseur pour des fournitures faites à un particulier pour ses usages domestiques se prescrit par deux ans et qu'aucun acte interruptif n'est prouvé ; Par ces motifs : déclare l'action prescrite."},{"min":45,"text":"Le Tribunal, attendu que la prescription semble acquise mais que le fournisseur offre de prouver une reconnaissance ; Par ces motifs : ordonne une enquête."},{"min":0,"text":"Le Tribunal, attendu que le client n'oppose pas utilement la prescription et ne prouve pas le paiement ; Par ces motifs : le condamne à payer 38 000 Dirhams."}]},{"id":"escroquerie","matiere":"penal","title":"Ministère public c/ Youssef A.","court":"Tribunal de première instance de Casablanca — chambre correctionnelle","object":"Poursuite pour escroquerie : vente en ligne d'un téléphone jamais livré.","you":"Avocat de la défense (Youssef A.)","adverseName":"Ministère public","facts":"Youssef A. a vendu sur internet un téléphone 6 500 DH. L'acheteur a payé par virement ; le téléphone n'est jamais arrivé. Youssef A. explique que son fournisseur ne l'a pas livré et il a remboursé l'acheteur deux mois plus tard, après le dépôt de la plainte. C'est sa seule vente en ligne.","rounds":[{"name":"L'élément matériel","adverse":"Monsieur le Président, le prévenu a encaissé 6 500 Dirhams pour un objet qu'il n'a jamais livré. L'escroquerie est constituée.","prompt":"Contestez la qualification.","options":[{"label":"Absence de manœuvres","detail":"L'escroquerie suppose d'induire astucieusement en erreur par des affirmations fallacieuses ; une simple inexécution ne suffit pas.","pts":17,"speech":"L'escroquerie exige que l'auteur ait induit astucieusement la victime en erreur, par des affirmations fallacieuses ou la dissimulation de faits vrais, en vue d'un profit illégitime. Une vente non livrée est d'abord une inexécution contractuelle. Le prévenu a utilisé son vrai nom et son vrai compte, n'a pas de faux profil, et a remboursé.","ok":["Rappelle les éléments constitutifs","Distingue inexécution et escroquerie","Relève l'identité réelle utilisée"],"ko":[]},{"label":"Plaider la clémence","detail":"Demander l'indulgence sans contester les faits.","pts":7,"speech":"Mon client regrette, il est jeune.","ok":[],"ko":["Ne conteste pas la qualification"]}],"concepts":[{"label":"Pas de manœuvres frauduleuses / affirmations fallacieuses","re":"manoeuvre|astuc|fallaci|tromp","pts":6,"key":true},{"label":"Simple inexécution contractuelle","re":"inexecution|civil|contractuel","pts":5},{"label":"Identité réelle / remboursement","re":"vrai nom|identite|rembours","pts":3}],"articles":[{"code":"CP","article":"540","label":"Art. 540 Code pénal (escroquerie)","pts":4}],"faille":"La défense ne conteste pas les faits : l'escroquerie est caractérisée.","concede":"Il n'y a pas de faux profil, c'est vrai. Mais l'intention reste à examiner."},{"name":"L'intention","adverse":"Le remboursement est intervenu après la plainte : il ne fait pas disparaître l'infraction.","prompt":"Plaidez sur l'élément intentionnel.","options":[{"label":"Bonne foi démontrée","detail":"Preuves de la commande au fournisseur ; l'intention s'apprécie au jour de la vente.","pts":15,"speech":"L'intention s'apprécie au moment de la vente. Nous produisons la commande passée au fournisseur et les messages relançant celui-ci : au jour de la vente, le prévenu croyait pouvoir livrer. Le remboursement confirme cette bonne foi.","ok":["Situe l'intention au jour de la vente","Produit des preuves"],"ko":[]},{"label":"Admettre l'intention","detail":"Concéder qu'il savait ne pas pouvoir livrer.","pts":3,"speech":"Il savait que ce serait difficile.","ok":[],"ko":["Aveu de l'élément moral"]}],"concepts":[{"label":"Intention appréciée au jour de la vente","re":"jour de la vente|moment|au moment","pts":5,"key":true},{"label":"Preuves de la commande au fournisseur","re":"commande|fournisseur|messages","pts":4}],"articles":[],"faille":"L'élément intentionnel est établi.","concede":"Le doute profite au prévenu."},{"name":"Réquisitions et peine","adverse":"Le ministère public requiert six mois d'emprisonnement avec sursis et une amende.","prompt":"Concluez.","options":[{"label":"Relaxe, subsidiairement peine minimale","detail":"Relaxe au bénéfice du doute ; subsidiairement, amende avec sursis.","pts":15,"speech":"Nous sollicitons la relaxe. À titre subsidiaire, compte tenu du remboursement intégral et d'un casier vierge, une simple amende avec sursis.","ok":["Conclusions hiérarchisées"],"ko":[]},{"label":"Accepter les réquisitions","detail":"Ne rien contester.","pts":6,"speech":"Nous nous en remettons.","ok":[],"ko":["Aucune défense de la peine"]}],"concepts":[{"label":"Relaxe","re":"relaxe|acquitt|doute","pts":4,"key":true},{"label":"Subsidiairement, peine réduite","re":"subsidiair|sursis|amende","pts":3}],"articles":[],"faille":"La défense ne discute pas la peine.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'existence d'affirmations fallacieuses et de l'intention frauduleuse au jour de la vente n'est pas établie, le litige relevant d'une inexécution contractuelle réparée ; Par ces motifs : relaxe le prévenu."},{"min":45,"text":"Le Tribunal, attendu que l'escroquerie est établie mais que le remboursement intégral justifie une peine modérée ; Par ces motifs : condamne le prévenu à une amende avec sursis."},{"min":0,"text":"Le Tribunal, attendu que le prévenu a encaissé le prix sans pouvoir livrer, sachant ne pas le pouvoir ; Par ces motifs : le condamne à six mois d'emprisonnement avec sursis."}]},{"id":"abus-confiance","matiere":"penal","title":"Société Atlas Électro c/ Hicham K.","court":"Tribunal de première instance de Rabat — chambre correctionnelle","object":"Abus de confiance : un commercial a gardé les encaissements clients.","you":"Avocat de la partie civile (Atlas Électro)","adverseName":"Avocat de Hicham K.","facts":"Hicham K., commercial, encaissait les paiements en espèces des clients et devait les reverser chaque semaine. Un audit montre que 142 000 DH encaissés sur huit mois n'ont jamais été reversés ; les reçus signés par Hicham K. sont au dossier. Il affirme que la société lui devait des commissions.","rounds":[{"name":"Les éléments de l'infraction","adverse":"Monsieur le Président, mon client n'a rien volé : la société lui devait des commissions, il s'est simplement payé.","prompt":"Caractérisez l'abus de confiance.","options":[{"label":"Détournement de fonds remis à titre précaire","detail":"Les fonds étaient remis à charge de les reverser ; les garder constitue un détournement.","pts":17,"speech":"Les fonds n'appartenaient pas au prévenu : il les recevait pour le compte de la société, à charge de les reverser chaque semaine. Les garder, c'est les détourner de mauvaise foi au préjudice de leur propriétaire. Les reçus qu'il a signés établissent chaque encaissement.","ok":["Identifie la remise précaire","Caractérise le détournement","S'appuie sur les reçus signés"],"ko":[]},{"label":"Parler de vol","detail":"Qualifier les faits de vol.","pts":7,"speech":"Le prévenu a volé l'argent de la société.","ok":[],"ko":["Mauvaise qualification : les fonds lui avaient été remis"]}],"concepts":[{"label":"Fonds remis à charge de les reverser","re":"remis|reverser|pour le compte|precaire","pts":5,"key":true},{"label":"Détournement de mauvaise foi","re":"detourn|mauvaise foi","pts":5},{"label":"Reçus signés / audit","re":"recu|audit","pts":3}],"articles":[{"code":"CP","article":"547","label":"Art. 547 Code pénal (abus de confiance)","pts":5}],"faille":"La partie civile qualifie mal les faits.","concede":"Les éléments matériels sont là. Reste la compensation."},{"name":"La compensation invoquée","adverse":"La société devait 40 000 Dirhams de commissions : il y a compensation.","prompt":"Répondez.","options":[{"label":"On ne se fait pas justice soi-même","detail":"Une créance contestée ne justifie pas de retenir les fonds d'autrui ; et elle couvrirait au mieux 40 000 DH.","pts":15,"speech":"Une créance de commissions, à la supposer fondée, se réclame devant le juge ; elle n'autorise pas à retenir les fonds confiés. De plus, 40 000 Dirhams ne justifient pas la rétention de 142 000 Dirhams. Les fiches de paie montrent d'ailleurs que les commissions ont été réglées.","ok":["Refuse la justice privée","Disproportion des montants","Produit les fiches de paie"],"ko":[]},{"label":"Ignorer l'argument","detail":"Ne pas répondre.","pts":5,"speech":"La partie civile maintient sa demande.","ok":[],"ko":["Laisse la compensation sans réponse"]}],"concepts":[{"label":"Pas de justice privée / créance à réclamer en justice","re":"justice|reclam|retenir","pts":5,"key":true},{"label":"Disproportion 40 000 / 142 000","re":"142|disproportion","pts":4},{"label":"Fiches de paie","re":"fiche|paie|commission","pts":3}],"articles":[],"faille":"La compensation est plausible.","concede":"La compensation ne tient pas."},{"name":"Demandes civiles","adverse":"La défense propose un remboursement échelonné sur dix ans.","prompt":"Formulez les demandes de la partie civile.","options":[{"label":"Restitution intégrale + dommages","detail":"142 000 DH de restitution et des dommages pour le préjudice d'audit.","pts":15,"speech":"La partie civile demande la restitution des 142 000 Dirhams et 15 000 Dirhams de dommages-intérêts pour les frais d'audit, ainsi que la condamnation pénale du prévenu.","ok":["Demandes complètes et chiffrées"],"ko":[]},{"label":"Accepter dix ans","detail":"Accepter l'échéancier.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Aucune garantie de paiement"]}],"concepts":[{"label":"Restitution intégrale","re":"142|restitution","pts":4,"key":true},{"label":"Dommages pour les frais d'audit","re":"audit|dommages","pts":3}],"articles":[],"faille":"La partie civile ne chiffre pas ses demandes.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le prévenu a détourné de mauvaise foi des fonds remis à charge de les reverser, sans que la compensation invoquée soit justifiée ; Par ces motifs : le déclare coupable d'abus de confiance et le condamne à restituer 142 000 Dirhams et à verser 15 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que l'abus de confiance est établi ; Par ces motifs : condamne le prévenu à restituer 102 000 Dirhams, déduction faite des commissions alléguées."},{"min":0,"text":"Le Tribunal, attendu que la partie civile qualifie mal les faits et que la créance invoquée rend la situation équivoque ; Par ces motifs : renvoie la partie civile à mieux se pourvoir."}]},{"id":"garde-a-vue","matiere":"penal","title":"Ministère public c/ Karim B.","court":"Tribunal de première instance de Tanger — chambre correctionnelle","object":"Vol d'un scooter : nullité de la garde à vue et du procès-verbal.","you":"Avocat de la défense (Karim B.)","adverseName":"Ministère public","facts":"Karim B. a été arrêté pour le vol d'un scooter. Il a été gardé à vue 70 heures sans prolongation écrite du parquet. Le procès-verbal ne mentionne ni l'heure du début de la garde à vue ni les heures d'audition, et ne porte pas sa signature. Ses aveux ne figurent que dans ce procès-verbal ; aucun témoin ne l'a vu prendre le scooter.","rounds":[{"name":"La durée de la garde à vue","adverse":"Monsieur le Président, les aveux du prévenu sont clairs : il a reconnu le vol.","prompt":"Soulevez l'irrégularité de la garde à vue.","options":[{"label":"Dépassement de la durée légale","detail":"La garde à vue ne peut excéder 48 heures sans prolongation autorisée par le parquet.","pts":17,"speech":"Le Code de procédure pénale limite la garde à vue à quarante-huit heures à compter de l'arrestation, sauf prolongation autorisée par le ministère public. Karim B. a été retenu soixante-dix heures sans aucune autorisation écrite. La mesure est irrégulière et les déclarations recueillies pendant ce temps doivent être écartées.","ok":["Cite la durée légale de 48 heures","Relève l'absence de prolongation","Demande d'écarter les déclarations"],"ko":[]},{"label":"Contester les aveux sur le fond","detail":"Dire que les aveux sont faux.","pts":8,"speech":"Mon client n'a jamais avoué.","ok":[],"ko":["Ne soulève pas la nullité, pourtant décisive"]}],"concepts":[{"label":"Durée de 48 heures","re":"48|quarante-huit","pts":6,"key":true},{"label":"Absence de prolongation du parquet","re":"prolongation|parquet|ministere public|autoris","pts":5},{"label":"Nullité / écarter les déclarations","re":"nul|ecart|irregul","pts":3}],"articles":[{"code":"CPP","article":"66","label":"Art. 66 CPP (durée de la garde à vue)","pts":5}],"faille":"La défense ne soulève aucune nullité : les aveux sont réguliers.","concede":"La durée est dépassée. Reste le procès-verbal."},{"name":"Le procès-verbal","adverse":"Les irrégularités du procès-verbal sont de simples oublis matériels.","prompt":"Répondez sur le procès-verbal.","options":[{"label":"Mentions obligatoires manquantes","detail":"Le PV doit mentionner les heures de garde à vue et d'audition et être signé par l'intéressé.","pts":16,"speech":"La loi impose que le procès-verbal mentionne le jour et l'heure du début et de la fin de la garde à vue et des auditions, et qu'il soit signé par la personne entendue ou porte la mention de son refus. Aucune de ces garanties n'est respectée. Un acte qui ne prouve pas l'accomplissement régulier des formalités est réputé non accompli.","ok":["Énumère les mentions obligatoires","Tire la conséquence sur la valeur du PV"],"ko":[]},{"label":"Accepter le PV","detail":"Ne pas discuter.","pts":4,"speech":"Nous ne contestons pas le procès-verbal.","ok":[],"ko":["Renonce à une nullité sérieuse"]}],"concepts":[{"label":"Heures de garde à vue et d'audition","re":"heure|horaire","pts":5,"key":true},{"label":"Signature du prévenu","re":"signature|signe","pts":4},{"label":"Acte réputé non accompli / nullité","re":"nul|non accompli|ecart","pts":3}],"articles":[{"code":"CPP","article":"67","label":"Art. 67 CPP (mentions du procès-verbal)","pts":4},{"code":"CPP","article":"751","label":"Art. 751 CPP (acte irrégulier réputé non accompli)","pts":2}],"faille":"Les irrégularités sont mineures.","concede":"Le procès-verbal est fragile."},{"name":"Le fond et la peine","adverse":"Même sans aveux, le scooter a été retrouvé près du domicile du prévenu.","prompt":"Concluez.","options":[{"label":"Relaxe faute de preuve régulière","detail":"Sans aveux réguliers, la proximité ne prouve pas la soustraction.","pts":15,"speech":"Une fois les déclarations écartées, il reste un scooter retrouvé dans une rue fréquentée, près de plusieurs immeubles. Cela ne prouve pas la soustraction frauduleuse par Karim B. Nous sollicitons la relaxe.","ok":["Raisonne sans les preuves annulées","Relève l'insuffisance de l'indice"],"ko":[]},{"label":"Demander une peine légère","detail":"Admettre la culpabilité.","pts":6,"speech":"Nous demandons une peine avec sursis.","ok":[],"ko":["Abandonne les nullités"]}],"concepts":[{"label":"Relaxe / insuffisance de preuves","re":"relaxe|preuve|doute","pts":4,"key":true},{"label":"Soustraction non prouvée","re":"soustraction|proximite","pts":3}],"articles":[{"code":"CP","article":"505","label":"Art. 505 Code pénal (vol)","pts":2}],"faille":"La défense admet la culpabilité.","concede":"Le doute est réel."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la garde à vue a excédé la durée légale sans prolongation et que le procès-verbal ne comporte pas les mentions obligatoires ; que les déclarations doivent être écartées et que les autres éléments sont insuffisants ; Par ces motifs : relaxe le prévenu."},{"min":45,"text":"Le Tribunal, attendu que les déclarations recueillies irrégulièrement sont écartées, mais qu'il subsiste un doute ; Par ces motifs : relaxe le prévenu au bénéfice du doute."},{"min":0,"text":"Le Tribunal, attendu qu'aucune nullité n'est utilement soulevée et que les aveux sont circonstanciés ; Par ces motifs : condamne le prévenu à un an d'emprisonnement pour vol."}]},{"id":"violences","matiere":"penal","title":"Ministère public c/ Saïd M.","court":"Tribunal de première instance de Marrakech — chambre correctionnelle","object":"Violences volontaires lors d'une dispute de voisinage : qualification et certificat médical.","you":"Avocat de la défense (Saïd M.)","adverseName":"Ministère public","facts":"Au cours d'une dispute de stationnement, Saïd M. a poussé son voisin, qui est tombé. Le premier certificat médical mentionne une incapacité de 12 jours ; un second certificat, établi trois semaines plus tard par un autre médecin à la demande de la victime, mentionne 25 jours. Le parquet poursuit sur la base du second certificat.","rounds":[{"name":"La qualification","adverse":"Monsieur le Président, le certificat fait état de 25 jours d'incapacité : la peine aggravée s'applique.","prompt":"Contestez la qualification aggravée.","options":[{"label":"Seuil des 20 jours contesté","detail":"La qualification aggravée suppose une incapacité de plus de 20 jours ; le premier certificat, contemporain des faits, retient 12 jours.","pts":17,"speech":"La qualification aggravée suppose une incapacité supérieure à vingt jours. Le seul certificat contemporain des faits retient douze jours ; le second, établi trois semaines plus tard par un autre médecin, à la demande de la victime, ne précise pas pourquoi l'incapacité aurait doublé. Les faits relèvent au plus des violences simples.","ok":["Identifie le seuil des 20 jours","Compare les deux certificats","Demande la requalification"],"ko":[]},{"label":"Nier les faits","detail":"Dire qu'il n'y a jamais eu de contact.","pts":5,"speech":"Mon client n'a jamais touché la victime.","ok":[],"ko":["Contredit les témoins et le dossier"]}],"concepts":[{"label":"Seuil de vingt jours","re":"vingt jours|20 jours|plus de 20|superieure","pts":6,"key":true},{"label":"Compare les certificats / le premier est contemporain","re":"certificat|12 jours|douze|contemporain","pts":5},{"label":"Requalification en violences simples","re":"requalif|simple","pts":3}],"articles":[{"code":"CP","article":"401","label":"Art. 401 Code pénal (incapacité supérieure à 20 jours)","pts":3},{"code":"CP","article":"400","label":"Art. 400 Code pénal (violences volontaires)","pts":3}],"faille":"La défense ne conteste pas le certificat : la qualification aggravée est retenue.","concede":"Le second certificat est discutable. Le tribunal peut ordonner une expertise."},{"name":"Les circonstances","adverse":"Le prévenu a agi avec violence, sans provocation.","prompt":"Plaidez les circonstances.","options":[{"label":"Geste unique dans une altercation réciproque","detail":"Une poussée unique, sans arme, dans une dispute où la victime a aussi été agressive (témoin).","pts":14,"speech":"Il s'agit d'une poussée unique, sans arme ni préméditation, au cours d'une altercation où la victime elle-même avait saisi le prévenu par le col, comme l'atteste un voisin. Ces circonstances doivent être prises en compte dans la peine.","ok":["Geste unique, sans arme","Altercation réciproque attestée"],"ko":[]},{"label":"Accuser la victime","detail":"Dire que la victime a simulé.","pts":5,"speech":"La victime exagère tout.","ok":[],"ko":["Attitude contre-productive"]}],"concepts":[{"label":"Geste unique / sans arme ni préméditation","re":"unique|sans arme|premedit","pts":4,"key":true},{"label":"Comportement de la victime attesté","re":"victime.*(col|saisi|agress)|temoin|atteste","pts":4}],"articles":[],"faille":"Le prévenu ne manifeste aucun regret.","concede":"Les circonstances sont atténuantes."},{"name":"Peine et réparation","adverse":"La victime réclame 50 000 DH de dommages-intérêts.","prompt":"Concluez.","options":[{"label":"Requalification, amende, réparation mesurée","detail":"Violences simples, amende ou sursis, dommages limités au préjudice prouvé.","pts":15,"speech":"Nous demandons la requalification en violences simples, une peine d'amende ou d'emprisonnement avec sursis, et une réparation limitée au préjudice justifié, au besoin après expertise médicale.","ok":["Conclusions complètes"],"ko":[]},{"label":"Accepter tout","detail":"Ne pas discuter.","pts":6,"speech":"Nous nous en remettons.","ok":[],"ko":["Aucune défense"]}],"concepts":[{"label":"Requalification et peine modérée","re":"requalif|sursis|amende","pts":4,"key":true},{"label":"Expertise médicale","re":"expert","pts":3}],"articles":[],"faille":"La défense ne discute pas la peine.","concede":"Les conclusions sont mesurées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que seul le certificat contemporain des faits est probant et retient une incapacité de douze jours ; Par ces motifs : requalifie en violences simples et condamne le prévenu à une amende, ainsi qu'à 8 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que la durée de l'incapacité est incertaine ; Par ces motifs : ordonne une expertise médicale avant dire droit."},{"min":0,"text":"Le Tribunal, attendu que l'incapacité est supérieure à vingt jours ; Par ces motifs : condamne le prévenu à un an d'emprisonnement et à 30 000 Dirhams de dommages-intérêts."}]},{"id":"cheque-penal","matiere":"penal","title":"Ministère public c/ Nadia R.","court":"Tribunal de première instance d'Agadir — chambre correctionnelle","object":"Émission de chèque sans provision : 48 000 DH.","you":"Avocat de la défense (Nadia R.)","adverseName":"Ministère public","facts":"Nadia R., gérante d'un salon de coiffure, a remis un chèque de 48 000 DH à un fournisseur. Le chèque a été rejeté pour insuffisance de provision. Elle a régularisé en déposant la somme sur le compte et en payant le fournisseur douze jours après le rejet, avant toute citation. Le fournisseur s'est désisté de sa plainte.","rounds":[{"name":"L'infraction","adverse":"Monsieur le Président, le chèque a été émis sans provision suffisante : l'infraction est constituée au jour de l'émission.","prompt":"Présentez la défense.","options":[{"label":"Régularisation et absence d'intention","detail":"Provision constituée et créancier payé rapidement ; démontrer la bonne foi.","pts":16,"speech":"Nadia R. a régularisé la situation douze jours après le rejet, avant toute poursuite : la provision a été constituée et le fournisseur intégralement payé, puis s'est désisté. L'insuffisance résultait d'un virement client attendu et retardé, dont nous produisons la preuve. Ces éléments écartent la mauvaise foi.","ok":["Met en avant la régularisation rapide","Produit la preuve du virement attendu","Mentionne le désistement"],"ko":[]},{"label":"Nier l'émission","detail":"Dire que le chèque a été volé.","pts":4,"speech":"Ce chèque a été volé.","ok":[],"ko":["Version incompatible avec le paiement effectué"]}],"concepts":[{"label":"Régularisation / provision constituée","re":"regularis|provision|depos|paye","pts":6,"key":true},{"label":"Bonne foi / virement attendu","re":"bonne foi|virement|attendu|retard","pts":4},{"label":"Désistement du fournisseur","re":"desist","pts":3}],"articles":[{"code":"CCOM","article":"316","label":"Art. 316 Code de commerce (chèque sans provision)","pts":4}],"faille":"La défense n'apporte aucun élément de bonne foi.","concede":"La régularisation est établie. Elle pèsera sur la peine."},{"name":"La portée du désistement","adverse":"Le désistement de la victime n'éteint pas l'action publique.","prompt":"Répondez.","options":[{"label":"Admettre et plaider la peine","detail":"Reconnaître que l'action publique subsiste, mais demander une peine minimale.","pts":14,"speech":"Il est exact que le désistement n'éteint pas l'action publique. Mais il témoigne de la réparation intégrale du préjudice, que le tribunal doit prendre en compte pour individualiser la peine.","ok":["Position juridiquement exacte","Oriente vers la peine"],"ko":[]},{"label":"Soutenir l'extinction","detail":"Affirmer que le désistement met fin aux poursuites.","pts":6,"speech":"Le désistement met fin à l'affaire.","ok":[],"ko":["Erreur de droit"]}],"concepts":[{"label":"Le désistement n'éteint pas l'action publique","re":"action publique|n.eteint pas|subsist","pts":5,"key":true},{"label":"Réparation intégrale","re":"repar|integral","pts":3}],"articles":[],"faille":"La défense se trompe sur le droit.","concede":"La position est exacte."},{"name":"La peine","adverse":"Le ministère public requiert un an d'emprisonnement avec sursis et l'amende légale.","prompt":"Concluez.","options":[{"label":"Peine minimale, sursis","detail":"Amende au minimum, sursis, compte tenu de la régularisation.","pts":14,"speech":"Compte tenu de la régularisation avant poursuites, d'un casier vierge et du désistement, nous sollicitons l'application la plus clémente : amende au minimum légal et, le cas échéant, sursis.","ok":["Individualisation argumentée"],"ko":[]},{"label":"Se taire","detail":"Ne rien demander.","pts":6,"speech":"Nous nous en remettons.","ok":[],"ko":["Aucune défense de la peine"]}],"concepts":[{"label":"Peine minimale / sursis","re":"minimum|sursis|clemen","pts":4,"key":true}],"articles":[],"faille":"La défense ne discute pas la peine.","concede":"La demande est argumentée."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'infraction est constituée mais que la prévenue a régularisé avant toute poursuite et désintéressé intégralement le créancier ; Par ces motifs : la condamne à l'amende minimale avec sursis."},{"min":45,"text":"Le Tribunal, attendu que l'infraction est établie et que la régularisation justifie une peine modérée ; Par ces motifs : la condamne à six mois d'emprisonnement avec sursis et à l'amende légale."},{"min":0,"text":"Le Tribunal, attendu que la prévenue ne justifie d'aucune circonstance favorable ; Par ces motifs : la condamne à un an d'emprisonnement et à l'amende légale."}]},{"id":"faux-commerce","matiere":"penal","title":"Banque du Nord c/ Mehdi T.","court":"Tribunal de première instance de Casablanca — chambre correctionnelle","object":"Faux en écriture de commerce : bilans falsifiés pour obtenir un crédit.","you":"Avocat de la partie civile (Banque du Nord)","adverseName":"Avocat de Mehdi T.","facts":"Pour obtenir un crédit de 1,5 million de DH, Mehdi T., gérant d'une société de négoce, a remis à la banque des bilans montrant un bénéfice de 900 000 DH. Les bilans déposés au greffe et à l'administration fiscale font apparaître une perte de 300 000 DH. Le crédit n'est plus remboursé.","rounds":[{"name":"Le faux","adverse":"Monsieur le Président, mon client n'a fait qu'une présentation optimiste. La banque devait vérifier.","prompt":"Caractérisez le faux.","options":[{"label":"Altération frauduleuse de la vérité dans un écrit de commerce","detail":"Le faux est l'altération frauduleuse de la vérité dans un écrit, de nature à causer un préjudice ; les bilans sont des écritures de commerce.","pts":17,"speech":"Le faux en écritures est l'altération frauduleuse de la vérité, de nature à causer un préjudice, accomplie dans un écrit. Présenter un bénéfice de 900 000 Dirhams quand les comptes officiels montrent une perte de 300 000 Dirhams n'est pas de l'optimisme : c'est une altération. Les bilans d'une société sont des écritures de commerce, ce qui fonde une qualification spécifique.","ok":["Définit le faux","Compare les bilans","Qualifie d'écriture de commerce"],"ko":[]},{"label":"Parler d'escroquerie seulement","detail":"Qualifier uniquement d'escroquerie.","pts":9,"speech":"Le prévenu a escroqué la banque.","ok":["Qualification envisageable"],"ko":["Omet le faux, plus précis"]}],"concepts":[{"label":"Altération frauduleuse de la vérité","re":"alter|fausse|falsif","pts":6,"key":true},{"label":"Comparaison avec les bilans officiels","re":"greffe|fiscal|officiel|perte","pts":4},{"label":"Écriture de commerce","re":"ecriture de commerce|commerce","pts":3}],"articles":[{"code":"CP","article":"351","label":"Art. 351 Code pénal (définition du faux)","pts":3},{"code":"CP","article":"357","label":"Art. 357 Code pénal (faux en écriture de commerce)","pts":3}],"faille":"La partie civile ne démontre pas l'altération.","concede":"L'écart des bilans est troublant. Mais la banque a-t-elle été négligente ?"},{"name":"La négligence de la banque","adverse":"La banque aurait dû consulter les comptes déposés au greffe : sa négligence exclut son préjudice.","prompt":"Répondez.","options":[{"label":"La négligence n'efface pas l'infraction","detail":"Le faux est punissable dès qu'il est de nature à causer un préjudice ; la victime n'a pas à soupçonner les documents remis.","pts":15,"speech":"Le faux est constitué dès lors que l'écrit est de nature à causer un préjudice, et il en a causé un : 1,5 million de Dirhams de crédit. Une banque peut se fier à des bilans signés par le gérant ; l'éventuel défaut de vérification ne fait pas disparaître la fraude.","ok":["Préjudice potentiel et réel","Écarte la négligence comme excuse"],"ko":[]},{"label":"Admettre la négligence","detail":"Concéder la faute de la banque.","pts":5,"speech":"La banque aurait pu mieux vérifier.","ok":[],"ko":["Fragilise la demande civile"]}],"concepts":[{"label":"De nature à causer un préjudice","re":"nature a causer|prejudice","pts":5,"key":true},{"label":"La négligence n'excuse pas la fraude","re":"neglig|fier|confiance","pts":4}],"articles":[],"faille":"La négligence de la banque est établie.","concede":"La fraude subsiste malgré la négligence alléguée."},{"name":"Demandes civiles","adverse":"Le prévenu propose de rembourser sur quinze ans.","prompt":"Formulez les demandes.","options":[{"label":"Condamnation et réparation","detail":"Condamnation pénale, remboursement du capital restant dû et dommages.","pts":15,"speech":"La partie civile demande la condamnation du prévenu, le paiement du capital restant dû et des dommages-intérêts pour le préjudice né de la fraude.","ok":["Demandes complètes"],"ko":[]},{"label":"Accepter quinze ans","detail":"Accepter l'échéancier.","pts":7,"speech":"La banque accepte.","ok":[],"ko":["Aucune garantie"]}],"concepts":[{"label":"Condamnation et capital restant dû","re":"capital|rembours|condamn","pts":4,"key":true}],"articles":[],"faille":"La partie civile ne chiffre pas ses demandes.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le prévenu a remis des bilans altérés frauduleusement, écritures de commerce de nature à causer un préjudice ; Par ces motifs : le déclare coupable de faux en écriture de commerce, le condamne à deux ans d'emprisonnement et au paiement du capital restant dû."},{"min":45,"text":"Le Tribunal, attendu que le faux est établi mais que la banque a contribué au dommage ; Par ces motifs : condamne le prévenu et réduit les dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu que l'altération n'est pas démontrée avec certitude ; Par ces motifs : relaxe le prévenu."}]},{"id":"faute-grave","matiere":"travail","title":"Mme Bennis c/ Société Textiles du Nord","court":"Tribunal de première instance de Tanger — chambre sociale","object":"Licenciement pour faute grave sans audition préalable.","you":"Avocat de la salariée (Mme Bennis)","adverseName":"Avocat de l'employeur","facts":"Mme Bennis, chef d'équipe depuis huit ans, a été licenciée pour « faute grave » après une altercation verbale avec un superviseur. Elle n'a jamais été convoquée à un entretien ; la lettre de licenciement lui a été remise neuf jours après les faits.","rounds":[{"name":"La procédure","adverse":"Monsieur le Président, la salariée a insulté son supérieur : c'est une faute grave, le licenciement est justifié.","prompt":"Contestez la procédure.","options":[{"label":"Défaut d'audition et délai","detail":"Avant le licenciement, le salarié doit être entendu en présence d'un délégué ; la décision est notifiée dans les 48 heures.","pts":18,"speech":"Avant tout licenciement, le salarié doit pouvoir se défendre et être entendu par l'employeur, en présence d'un délégué des salariés ou d'un représentant syndical de son choix. Mme Bennis n'a jamais été entendue. De plus, la décision doit être remise dans les 48 heures suivant la décision : elle l'a été neuf jours après les faits, sans entretien.","ok":["Identifie l'obligation d'audition","Mentionne la présence du délégué","Relève le délai de notification"],"ko":[]},{"label":"Contester l'insulte","detail":"Dire qu'elle n'a pas insulté.","pts":9,"speech":"Mme Bennis n'a jamais insulté personne.","ok":["Défense sur le fond"],"ko":["Oublie la procédure, décisive"]}],"concepts":[{"label":"Audition préalable obligatoire","re":"audition|entendu|se defendre|entretien","pts":6,"key":true},{"label":"Présence du délégué / représentant","re":"delegue|syndical|representant","pts":4},{"label":"Délai de notification de 48 heures","re":"48|quarante-huit","pts":4}],"articles":[{"code":"CT","article":"62","label":"Art. 62 Code du travail (audition préalable)","pts":4},{"code":"CT","article":"63","label":"Art. 63 Code du travail (notification de la décision)","pts":2}],"faille":"La salariée ne critique pas la procédure.","concede":"La procédure n'a pas été respectée. Reste la gravité des faits."},{"name":"La gravité de la faute","adverse":"L'insulte envers un supérieur figure parmi les fautes graves légales.","prompt":"Discutez la qualification.","options":[{"label":"Faute grave contestée","detail":"Les fautes graves sont limitativement décrites ; une altercation verbale isolée, provoquée, n'en relève pas forcément.","pts":15,"speech":"Le Code du travail énumère les fautes graves. Une altercation verbale isolée, en huit ans d'ancienneté sans aucune sanction, et provoquée selon deux témoins par les propos du superviseur, n'a pas la gravité requise. Au plus, une sanction disciplinaire graduée était envisageable.","ok":["Renvoie à la liste légale","Ancienneté sans sanction","Témoignages de provocation"],"ko":[]},{"label":"Admettre la faute","detail":"Reconnaître la faute grave.","pts":4,"speech":"Il est vrai que c'était grave.","ok":[],"ko":["Abandonne la contestation au fond"]}],"concepts":[{"label":"Liste légale des fautes graves","re":"faute grave|liste|enumer","pts":5,"key":true},{"label":"Ancienneté sans sanction / sanction graduée","re":"anciennete|sans sanction|gradu|avertissement","pts":4},{"label":"Provocation attestée","re":"provoc|temoin","pts":3}],"articles":[{"code":"CT","article":"39","label":"Art. 39 Code du travail (fautes graves)","pts":4}],"faille":"La faute grave est reconnue.","concede":"La gravité est discutable."},{"name":"Les indemnités","adverse":"L'employeur propose deux mois de salaire pour solde de tout compte.","prompt":"Chiffrez les demandes.","options":[{"label":"Licenciement abusif : indemnités complètes","detail":"Dommages pour licenciement abusif, indemnité de licenciement, préavis.","pts":15,"speech":"Le licenciement étant abusif, nous demandons des dommages-intérêts, l'indemnité légale de licenciement calculée sur huit ans d'ancienneté et l'indemnité compensatrice de préavis.","ok":["Demandes complètes"],"ko":[]},{"label":"Accepter deux mois","detail":"Transiger.","pts":7,"speech":"Mme Bennis accepte.","ok":[],"ko":["Bien en deçà de ses droits"]}],"concepts":[{"label":"Dommages pour licenciement abusif","re":"abusif|dommages","pts":4,"key":true},{"label":"Indemnité de licenciement et préavis","re":"indemnite|preavis","pts":3}],"articles":[{"code":"CT","article":"41","label":"Art. 41 Code du travail (rupture abusive)","pts":3}],"faille":"La salariée ne chiffre pas ses demandes.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la salariée n'a pas été entendue avant son licenciement et que l'altercation isolée ne constitue pas une faute grave ; Par ces motifs : déclare le licenciement abusif et condamne l'employeur aux dommages-intérêts, à l'indemnité de licenciement et au préavis."},{"min":45,"text":"Le Tribunal, attendu que la procédure d'audition n'a pas été respectée ; Par ces motifs : déclare le licenciement abusif et alloue les indemnités légales."},{"min":0,"text":"Le Tribunal, attendu que la faute grave est établie et que la procédure n'est pas utilement critiquée ; Par ces motifs : rejette la demande."}]},{"id":"licenciement-abusif","matiere":"travail","title":"M. El Amrani c/ Agence Voyages Plus","court":"Tribunal de première instance de Rabat — chambre sociale","object":"Licenciement verbal d'un salarié de 12 ans d'ancienneté : calcul des indemnités.","you":"Avocat du salarié (M. El Amrani)","adverseName":"Avocat de l'employeur","facts":"M. El Amrani, agent de réservation depuis 12 ans, a été renvoyé oralement par le directeur après une baisse d'activité, sans lettre ni procédure. L'employeur soutient qu'il a démissionné.","rounds":[{"name":"La rupture","adverse":"Monsieur le Président, le salarié a quitté son poste de lui-même : c'est une démission.","prompt":"Établissez le licenciement.","options":[{"label":"Licenciement verbal prouvé","detail":"Attestations de collègues, SMS du directeur ; une démission ne se présume pas.","pts":16,"speech":"Une démission suppose une volonté claire et non équivoque du salarié, qui n'existe pas ici. Deux collègues attestent avoir entendu le directeur lui dire de « ne plus revenir », et un SMS du directeur le confirme. Il s'agit d'un licenciement sans procédure, donc abusif, ouvrant droit à dommages-intérêts.","ok":["La démission ne se présume pas","Preuves du renvoi","Qualifie de licenciement abusif"],"ko":[]},{"label":"Plaider l'injustice","detail":"Dire que le salarié a été maltraité.","pts":7,"speech":"Mon client a été traité injustement.","ok":[],"ko":["Aucune preuve ni qualification"]}],"concepts":[{"label":"Pas de démission (volonté claire)","re":"demission|volonte|equivoque","pts":4,"key":true},{"label":"Preuves du renvoi (attestations, SMS)","re":"attest|sms|message|temoin","pts":5},{"label":"Licenciement abusif","re":"abusif","pts":4}],"articles":[{"code":"CT","article":"41","label":"Art. 41 Code du travail (rupture abusive)","pts":4}],"faille":"Le salarié ne prouve pas son licenciement.","concede":"Le renvoi est établi. Reste le calcul."},{"name":"L'indemnité de licenciement","adverse":"À supposer un licenciement, l'indemnité ne serait que d'un mois de salaire.","prompt":"Calculez l'indemnité légale.","options":[{"label":"Barème légal par tranches d'ancienneté","detail":"96 heures par an pour les 5 premières années, 144 heures de la 6e à la 10e, puis davantage au-delà.","pts":16,"speech":"L'indemnité de licenciement est due après six mois d'ancienneté. Elle se calcule par tranches : 96 heures de salaire pour chacune des cinq premières années, 144 heures pour la sixième à la dixième, puis le taux supérieur prévu par la loi pour les années suivantes. Sur douze ans, elle dépasse très largement un mois de salaire.","ok":["Applique le barème par tranches","Droit dès six mois d'ancienneté"],"ko":[]},{"label":"Demander un an de salaire","detail":"Réclamer un montant forfaitaire.","pts":7,"speech":"Nous demandons un an de salaire.","ok":[],"ko":["Aucun calcul légal"]}],"concepts":[{"label":"Barème par tranches (96 h / 144 h)","re":"96|144|tranche|heures","pts":6,"key":true},{"label":"Droit dès six mois","re":"six mois|6 mois","pts":3}],"articles":[{"code":"CT","article":"53","label":"Art. 53 Code du travail (barème de l'indemnité)","pts":4},{"code":"CT","article":"52","label":"Art. 52 Code du travail (droit à indemnité)","pts":2}],"faille":"Le calcul n'est pas fait.","concede":"Le barème est correctement appliqué."},{"name":"Les autres sommes","adverse":"L'employeur reconnaît devoir le dernier salaire.","prompt":"Concluez.","options":[{"label":"Demandes complètes","detail":"Dommages pour licenciement abusif, indemnité légale, préavis, salaire dû.","pts":15,"speech":"Nous demandons les dommages-intérêts pour licenciement abusif, l'indemnité légale de licenciement, l'indemnité compensatrice de préavis et le dernier salaire.","ok":["Complet"],"ko":[]},{"label":"Se limiter au salaire","detail":"Demander seulement le dernier salaire.","pts":6,"speech":"Nous demandons le dernier salaire.","ok":[],"ko":["Oublie l'essentiel"]}],"concepts":[{"label":"Dommages + indemnité + préavis","re":"dommages|indemnite|preavis","pts":4,"key":true}],"articles":[],"faille":"Le salarié oublie ses principales demandes.","concede":"Les demandes sont complètes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le salarié a été renvoyé verbalement sans procédure et qu'aucune démission n'est établie ; Par ces motifs : déclare le licenciement abusif et condamne l'employeur aux dommages-intérêts, à l'indemnité légale calculée selon le barème, au préavis et au salaire dû."},{"min":45,"text":"Le Tribunal, attendu que le licenciement est établi ; Par ces motifs : alloue l'indemnité légale et le préavis, et des dommages-intérêts modérés."},{"min":0,"text":"Le Tribunal, attendu que le salarié ne prouve pas la rupture à l'initiative de l'employeur ; Par ces motifs : rejette la demande, sauf le dernier salaire."}]},{"id":"heures-sup","matiere":"travail","title":"M. Fikri c/ Société Sécurité Atlas","court":"Tribunal de première instance de Casablanca — chambre sociale","object":"Rappel d'heures supplémentaires d'un agent de sécurité.","you":"Avocat du salarié (M. Fikri)","adverseName":"Avocat de l'employeur","facts":"M. Fikri, agent de sécurité, a travaillé pendant deux ans des postes de 12 heures, six jours sur sept, selon les plannings affichés. Ses bulletins de paie ne mentionnent aucune heure supplémentaire. L'employeur affirme que la rémunération est forfaitaire.","rounds":[{"name":"L'existence des heures","adverse":"Monsieur le Président, le salaire est un forfait qui couvre toutes les heures.","prompt":"Prouvez les heures supplémentaires.","options":[{"label":"Plannings et durée légale","detail":"Les plannings montrent des semaines bien au-delà de la durée normale ; les heures au-delà sont des heures supplémentaires.","pts":16,"speech":"Les plannings affichés par l'employeur lui-même montrent soixante-douze heures par semaine, bien au-delà de la durée normale de travail. Les heures supplémentaires se calculent au-delà de cette durée hebdomadaire. Aucun forfait écrit ne prévoit leur inclusion dans le salaire.","ok":["Preuve par les plannings de l'employeur","Calcul au-delà de la durée normale","Écarte le forfait non écrit"],"ko":[]},{"label":"Affirmer la fatigue","detail":"Dire que le travail était épuisant.","pts":6,"speech":"Mon client était épuisé.","ok":[],"ko":["Aucune preuve des heures"]}],"concepts":[{"label":"Plannings / preuve des horaires","re":"planning|horaire|72|douze heures|12 heures","pts":6,"key":true},{"label":"Au-delà de la durée normale","re":"duree normale|hebdomadaire|au-dela","pts":4},{"label":"Pas de forfait écrit","re":"forfait","pts":3}],"articles":[{"code":"CT","article":"196","label":"Art. 196 Code du travail (heures supplémentaires)","pts":3},{"code":"CT","article":"197","label":"Art. 197 Code du travail (calcul hebdomadaire)","pts":3}],"faille":"Le salarié ne prouve pas ses horaires.","concede":"Les plannings sont probants. Reste le calcul."},{"name":"Le calcul et la majoration","adverse":"À supposer des heures supplémentaires, elles ont été compensées par des jours de repos.","prompt":"Répondez.","options":[{"label":"Exiger la preuve des repos","detail":"L'employeur doit prouver les repos compensateurs ; les plannings ne les montrent pas.","pts":15,"speech":"Les plannings montrent six jours travaillés sur sept pendant deux ans, sans repos supplémentaire. Si l'employeur prétend avoir compensé, qu'il le prouve. Nous produisons un décompte semaine par semaine, avec la majoration légale.","ok":["Renverse l'argument des repos","Décompte détaillé avec majoration"],"ko":[]},{"label":"Demander un forfait","detail":"Réclamer 100 000 DH sans calcul.","pts":6,"speech":"Nous demandons 100 000 Dirhams.","ok":[],"ko":["Aucun calcul"]}],"concepts":[{"label":"Décompte semaine par semaine","re":"decompte|semaine|calcul","pts":5,"key":true},{"label":"Majoration","re":"majoration|majore","pts":4}],"articles":[],"faille":"Le salarié ne chiffre pas sa demande.","concede":"Le décompte est clair."},{"name":"Conclusions","adverse":"L'employeur propose un mois de salaire.","prompt":"Concluez.","options":[{"label":"Rappel intégral","detail":"Rappel des heures supplémentaires majorées et dommages pour défaut de paiement.","pts":14,"speech":"Nous demandons le rappel intégral des heures supplémentaires majorées selon le décompte, et la régularisation des bulletins de paie.","ok":["Demandes précises"],"ko":[]},{"label":"Accepter un mois","detail":"Transiger.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Très inférieur au dû"]}],"concepts":[{"label":"Rappel intégral","re":"rappel|integral|decompte","pts":4,"key":true}],"articles":[],"faille":"Le salarié ne précise pas sa demande.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les plannings établis par l'employeur démontrent des heures au-delà de la durée normale sans compensation prouvée ; Par ces motifs : condamne l'employeur au rappel des heures supplémentaires majorées selon le décompte produit."},{"min":45,"text":"Le Tribunal, attendu que des heures supplémentaires sont établies mais que le décompte doit être vérifié ; Par ces motifs : ordonne une expertise."},{"min":0,"text":"Le Tribunal, attendu que le salarié ne prouve pas ses horaires ; Par ces motifs : rejette la demande."}]},{"id":"periode-essai","matiere":"travail","title":"Mme Lamrani c/ Clinique Al Amal","court":"Tribunal de première instance de Fès — chambre sociale","object":"Rupture de la période d'essai d'une employée administrative.","you":"Avocat de l'employeur (Clinique Al Amal)","adverseName":"Avocat de Mme Lamrani","facts":"Mme Lamrani, employée administrative en CDI, payée au mois, a vu sa période d'essai rompue au bout de cinq semaines, par écrit, avec deux jours de préavis. Elle réclame six mois de salaire pour licenciement abusif.","rounds":[{"name":"La nature de la rupture","adverse":"Monsieur le Président, Mme Lamrani a été licenciée sans motif ni procédure : c'est un licenciement abusif.","prompt":"Présentez la défense de l'employeur.","options":[{"label":"Rupture de la période d'essai","detail":"Pendant l'essai, chaque partie peut rompre sans indemnité ; pour une employée, l'essai dure un mois et demi.","pts":17,"speech":"Il ne s'agit pas d'un licenciement : pendant la période d'essai, chacune des parties peut rompre le contrat sans indemnité. Pour les employés en CDI, la période d'essai est d'un mois et demi ; la rupture est intervenue au bout de cinq semaines, donc pendant l'essai.","ok":["Qualifie de rupture d'essai","Vérifie la durée légale de l'essai pour une employée"],"ko":[]},{"label":"Invoquer une faute","detail":"Accuser la salariée d'incompétence grave.","pts":7,"speech":"Mme Lamrani était incompétente.","ok":[],"ko":["Inutile et risqué : l'essai n'exige pas de motif"]}],"concepts":[{"label":"Rupture pendant la période d'essai","re":"periode d.essai|essai","pts":6,"key":true},{"label":"Un mois et demi pour une employée","re":"mois et demi|6 semaines|employe","pts":5},{"label":"Sans indemnité","re":"sans indemnite|sans preavis","pts":3}],"articles":[{"code":"CT","article":"13","label":"Art. 13 Code du travail (période d'essai)","pts":3},{"code":"CT","article":"14","label":"Art. 14 Code du travail (durée de l'essai)","pts":3}],"faille":"L'employeur ne démontre pas que la rupture est intervenue pendant l'essai.","concede":"La rupture est bien intervenue pendant l'essai. Mais le préavis ?"},{"name":"Le préavis minimal","adverse":"Après au moins une semaine de travail, la rupture de l'essai non motivée par une faute grave exige un délai de préavis.","prompt":"Répondez.","options":[{"label":"Reconnaître le préavis insuffisant, limiter la conséquence","detail":"Payée au mois, la salariée avait droit à huit jours : seuls les six jours manquants sont dus, pas un licenciement abusif.","pts":16,"speech":"Nous reconnaissons loyalement que, la salariée étant payée au mois, le préavis de rupture de l'essai devait être de huit jours, et non de deux. Mais cette irrégularité ne transforme pas la rupture de l'essai en licenciement abusif : elle ouvre droit seulement à la rémunération des six jours de préavis manquants.","ok":["Applique le bon délai (huit jours, paiement au mois)","Limite la sanction au préavis manquant"],"ko":[]},{"label":"Soutenir que deux jours suffisent","detail":"Affirmer que le préavis de deux jours est le délai légal.","pts":6,"speech":"Deux jours de préavis suffisent toujours.","ok":[],"ko":["Inexact : deux jours ne valent que pour les salariés payés à la journée, à la semaine ou à la quinzaine"]}],"concepts":[{"label":"Huit jours pour un salarié payé au mois","re":"huit jours|8 jours|paye au mois|au mois","pts":6,"key":true},{"label":"Seuls les jours manquants sont dus","re":"manquant|six jours|6 jours|remuneration du preavis","pts":4}],"articles":[{"code":"CT","article":"13","label":"Art. 13 Code du travail (préavis de rupture de l'essai)","pts":3}],"faille":"L'employeur prétend que deux jours suffisaient : c'est faux pour une salariée payée au mois.","concede":"Le préavis était insuffisant, l'employeur le reconnaît : la conséquence reste limitée."},{"name":"Conclusions","adverse":"La salariée réclame six mois de salaire.","prompt":"Concluez.","options":[{"label":"Rejet de l'abus, paiement du préavis manquant","detail":"Pas de licenciement abusif ; seuls six jours de préavis sont dus.","pts":15,"speech":"Nous concluons au rejet de la demande de dommages pour licenciement abusif, la rupture étant intervenue pendant l'essai, et offrons la rémunération des six jours de préavis manquants.","ok":["Conclusion exacte et loyale"],"ko":[]},{"label":"Proposer trois mois","detail":"Transiger.","pts":7,"speech":"La clinique propose trois mois.","ok":[],"ko":["Paie bien au-delà de l'obligation"]}],"concepts":[{"label":"Rejet de l'abus","re":"rejet|pas abusi","pts":4,"key":true},{"label":"Offre du préavis manquant","re":"six jours|6 jours|preavis manquant|manquant","pts":3}],"articles":[],"faille":"L'employeur n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la rupture est intervenue pendant la période d'essai d'un mois et demi applicable aux employés, mais que la salariée, payée au mois, avait droit à un préavis de huit jours ; Par ces motifs : rejette la demande pour licenciement abusif et condamne l'employeur à la rémunération de six jours de préavis."},{"min":45,"text":"Le Tribunal, attendu que la rupture est intervenue pendant l'essai avec un préavis insuffisant ; Par ces motifs : alloue une indemnité de préavis et des dommages modérés."},{"min":0,"text":"Le Tribunal, attendu que l'employeur n'a pas respecté le préavis légal et ne démontre pas une rupture régulière de l'essai ; Par ces motifs : déclare la rupture abusive."}]},{"id":"preavis","matiere":"travail","title":"Société Infotech c/ M. Zouhair","court":"Tribunal de première instance de Rabat — chambre sociale","object":"Démission sans préavis d'un ingénieur parti chez un concurrent.","you":"Avocat de l'employeur (Infotech)","adverseName":"Avocat de M. Zouhair","facts":"M. Zouhair, ingénieur en CDI depuis quatre ans, a démissionné par e-mail un vendredi et n'est plus revenu dès le lundi, rejoignant un concurrent. Infotech a dû recruter un prestataire en urgence pour finir un projet.","rounds":[{"name":"L'obligation de préavis","adverse":"Monsieur le Président, un salarié est libre de démissionner. Mon client n'a commis aucune faute.","prompt":"Fondez la demande de l'employeur.","options":[{"label":"Préavis obligatoire pour les deux parties","detail":"La rupture unilatérale d'un CDI, hors faute grave de l'autre partie, est subordonnée au respect du préavis ; à défaut, indemnité compensatrice.","pts":17,"speech":"La liberté de démissionner n'est pas en cause. Mais la rupture unilatérale d'un contrat à durée indéterminée est subordonnée, en l'absence de faute grave de l'autre partie, au respect du délai de préavis. Toute rupture sans préavis oblige la partie responsable à verser une indemnité égale à la rémunération de la période de préavis non observée.","ok":["Le préavis s'impose aussi au salarié","Identifie l'indemnité compensatrice"],"ko":[]},{"label":"Accuser de trahison","detail":"Reprocher le départ chez un concurrent.","pts":7,"speech":"Il est parti chez un concurrent, c'est une trahison.","ok":[],"ko":["Aucune règle invoquée"]}],"concepts":[{"label":"Préavis obligatoire en CDI","re":"preavis","pts":6,"key":true},{"label":"Indemnité compensatrice de préavis","re":"indemnite compensatrice|remuneration|periode de preavis","pts":5},{"label":"Absence de faute grave de l'employeur","re":"faute grave","pts":3}],"articles":[{"code":"CT","article":"43","label":"Art. 43 Code du travail (préavis)","pts":3},{"code":"CT","article":"51","label":"Art. 51 Code du travail (indemnité pour défaut de préavis)","pts":3}],"faille":"L'employeur ne fonde pas sa demande.","concede":"Le préavis était dû. Reste le préjudice supplémentaire."},{"name":"Le préjudice supplémentaire","adverse":"L'employeur ne peut réclamer plus que l'indemnité de préavis.","prompt":"Défendez les dommages complémentaires.","options":[{"label":"Rupture abusive par le salarié","detail":"La partie lésée par une rupture abusive peut demander des dommages-intérêts ; coût du prestataire justifié.","pts":14,"speech":"La loi permet à la partie lésée par une rupture abusive, quelle qu'elle soit, de demander des dommages-intérêts. Le départ du jour au lendemain, en plein projet, a obligé Infotech à payer un prestataire 60 000 Dirhams, factures à l'appui.","ok":["La rupture abusive peut venir du salarié","Préjudice justifié par factures"],"ko":[]},{"label":"Réclamer la perte du client","detail":"Demander 500 000 DH pour perte de marché.","pts":6,"speech":"Nous réclamons 500 000 Dirhams.","ok":[],"ko":["Préjudice non prouvé"]}],"concepts":[{"label":"La partie lésée peut demander des dommages","re":"partie lesee|dommages|abusi","pts":5,"key":true},{"label":"Coût du prestataire justifié","re":"prestataire|facture|60","pts":4}],"articles":[{"code":"CT","article":"41","label":"Art. 41 Code du travail (rupture abusive)","pts":3}],"faille":"Le préjudice supplémentaire n'est pas prouvé.","concede":"Le surcoût est justifié."},{"name":"Conclusions","adverse":"Le salarié propose d'effectuer une semaine de transition à distance.","prompt":"Concluez.","options":[{"label":"Indemnité de préavis + dommages justifiés","detail":"Indemnité compensatrice et coût du prestataire.","pts":14,"speech":"Nous demandons l'indemnité compensatrice de préavis et 60 000 Dirhams de dommages-intérêts justifiés par les factures du prestataire.","ok":["Demandes chiffrées"],"ko":[]},{"label":"Accepter la semaine","detail":"Transiger.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Ne couvre pas le préjudice"]}],"concepts":[{"label":"Indemnité et dommages chiffrés","re":"indemnite|dommages|60","pts":4,"key":true}],"articles":[],"faille":"L'employeur ne chiffre pas sa demande.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le salarié a rompu son contrat à durée indéterminée sans observer le préavis et que le surcoût subi par l'employeur est justifié ; Par ces motifs : le condamne à l'indemnité compensatrice de préavis et à 60 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que le préavis n'a pas été respecté ; Par ces motifs : condamne le salarié à l'indemnité compensatrice de préavis et rejette le surplus."},{"min":0,"text":"Le Tribunal, attendu que l'employeur ne fonde pas sa demande ; Par ces motifs : la rejette."}]},{"id":"chiqaq","matiere":"famille","title":"Mme Idrissi c/ M. Idrissi","court":"Tribunal de première instance de Meknès — section de la famille","object":"Divorce pour discorde (chiqaq) et droits de l'épouse.","you":"Avocat de l'épouse (Mme Idrissi)","adverseName":"Avocat de l'époux","facts":"Mariés depuis quatorze ans, trois enfants. Mme Idrissi demande le divorce pour discorde : le mari a quitté le domicile depuis un an et ne contribue plus aux charges. Le mari refuse le divorce et conteste toute somme.","rounds":[{"name":"La procédure de conciliation","adverse":"Monsieur le Président, mon client veut sauver son mariage ; le divorce ne peut être prononcé.","prompt":"Expliquez la procédure de discorde.","options":[{"label":"Tentative de conciliation puis divorce","detail":"Le tribunal doit tenter la conciliation ; en cas d'échec et de discorde persistante, il prononce le divorce.","pts":17,"speech":"En cas de discorde, le tribunal doit d'abord entreprendre toutes les tentatives de conciliation. Mais si la conciliation est impossible et que la discorde persiste, il en dresse procès-verbal et prononce le divorce. Le refus de l'époux n'y fait pas obstacle : un an d'abandon du domicile témoigne d'une discorde durable.","ok":["Décrit la procédure de conciliation","Le refus d'un époux n'empêche pas le divorce","Établit la discorde durable"],"ko":[]},{"label":"Accuser le mari","detail":"Énumérer ses torts sans procédure.","pts":8,"speech":"Le mari est seul responsable de tout.","ok":[],"ko":["N'explique pas la procédure applicable"]}],"concepts":[{"label":"Tentative de conciliation","re":"concilia","pts":5,"key":true},{"label":"Discorde persistante → divorce","re":"discorde|persist|chiqaq","pts":5},{"label":"Le refus de l'époux n'empêche pas","re":"refus|n.empeche pas|obstacle","pts":3}],"articles":[{"code":"CF","article":"94","label":"Art. 94 Code de la famille (conciliation)","pts":3},{"code":"CF","article":"97","label":"Art. 97 Code de la famille (prononcé du divorce)","pts":3}],"faille":"L'épouse ne démontre pas la discorde.","concede":"La discorde est établie. Reste la question des droits."},{"name":"Les droits de l'épouse","adverse":"Aucune somme n'est due : c'est l'épouse qui demande le divorce.","prompt":"Défendez les droits de l'épouse.","options":[{"label":"Droits légaux de l'épouse","detail":"Reliquat du sadaq, pension de viduité, don de consolation selon la durée du mariage.","pts":16,"speech":"Les droits dus à l'épouse comprennent le reliquat du sadaq, la pension de la période de viduité et le don de consolation, évalué notamment en fonction de la durée du mariage et de la situation financière de l'époux. Quatorze ans de mariage justifient une mout'â significative ; le tribunal tient compte de la responsabilité de chacun dans la discorde.","ok":["Énumère les droits légaux","Lie la mout'â à la durée du mariage","Responsabilité du mari dans la discorde"],"ko":[]},{"label":"Réclamer la maison","detail":"Demander la propriété du domicile.","pts":6,"speech":"Mme Idrissi veut la maison.","ok":[],"ko":["Sans fondement juridique"]}],"concepts":[{"label":"Sadaq / viduité / don de consolation","re":"sadaq|viduite|idda|consolation|mout","pts":6,"key":true},{"label":"Durée du mariage et ressources de l'époux","re":"duree|quatorze|ressources|situation financiere","pts":4}],"articles":[{"code":"CF","article":"84","label":"Art. 84 Code de la famille (droits de l'épouse)","pts":4}],"faille":"L'épouse ne justifie pas ses droits.","concede":"Les droits sont fondés."},{"name":"Les enfants","adverse":"Le mari propose 1 000 DH par mois pour les trois enfants.","prompt":"Concluez sur les enfants.","options":[{"label":"Pension, logement et garde","detail":"Pension selon les besoins et le niveau de vie, logement distinct, garde à la mère.","pts":15,"speech":"Nous demandons la garde des trois enfants, une pension alimentaire fixée selon leurs besoins et leur scolarité antérieure au divorce, et les frais de logement, distincts de la pension.","ok":["Couvre pension, logement et garde"],"ko":[]},{"label":"Accepter 1 000 DH","detail":"Transiger.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Manifestement insuffisant pour trois enfants"]}],"concepts":[{"label":"Pension selon besoins / scolarité","re":"pension|besoin|scolar","pts":4,"key":true},{"label":"Logement distinct / garde","re":"logement|garde","pts":3}],"articles":[{"code":"CF","article":"85","label":"Art. 85 Code de la famille (pension des enfants)","pts":3}],"faille":"L'épouse ne précise pas ses demandes pour les enfants.","concede":"Les demandes sont complètes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la conciliation a échoué et que la discorde persiste, imputable pour l'essentiel à l'époux ; Par ces motifs : prononce le divorce pour discorde, alloue à l'épouse le reliquat du sadaq, la pension de viduité et une mout'â de 60 000 Dirhams, lui confie la garde et fixe la pension et le logement des enfants."},{"min":45,"text":"Le Tribunal, attendu que la discorde est établie ; Par ces motifs : prononce le divorce, alloue les droits légaux avec une mout'â de 25 000 Dirhams et fixe la pension des enfants."},{"min":0,"text":"Le Tribunal, attendu que la discorde n'est pas suffisamment établie ; Par ces motifs : renvoie les parties à une nouvelle tentative de conciliation."}]},{"id":"pension","matiere":"famille","title":"Mme Kabbaj c/ M. Squalli","court":"Tribunal de première instance de Casablanca — section de la famille","object":"Fixation de la pension alimentaire et des frais de logement de deux enfants.","you":"Avocat de la mère (Mme Kabbaj)","adverseName":"Avocat du père","facts":"Divorcés depuis un an, Mme Kabbaj a la garde de deux enfants scolarisés en école privée. M. Squalli, cadre bancaire, déclare un salaire de 9 000 DH mais possède deux appartements loués. Il verse 1 500 DH par mois et refuse de payer le loyer de l'appartement où vivent les enfants.","rounds":[{"name":"Le contenu de la pension","adverse":"Monsieur le Président, 1 500 Dirhams suffisent : c'est ce que mon client peut payer.","prompt":"Définissez ce que couvre la pension.","options":[{"label":"Entretien complet et niveau de vie","detail":"La pension couvre alimentation, habillement, soins, instruction ; elle tient compte de la situation antérieure.","pts":16,"speech":"L'entretien comprend l'alimentation, l'habillement, les soins médicaux, l'instruction des enfants et tout ce qui est habituellement indispensable. Les enfants étaient scolarisés en école privée avant le divorce : leur situation scolaire doit être maintenue. 1 500 Dirhams ne couvrent même pas les frais de scolarité.","ok":["Contenu légal de l'entretien","Maintien du niveau de vie et de la scolarité"],"ko":[]},{"label":"Demander un montant élevé sans justification","detail":"Réclamer 20 000 DH.","pts":7,"speech":"Nous demandons 20 000 Dirhams.","ok":[],"ko":["Aucune justification des besoins"]}],"concepts":[{"label":"Contenu de l'entretien (alimentation, soins, instruction)","re":"aliment|habill|soins|instruction|scolar","pts":6,"key":true},{"label":"Maintien de la situation antérieure","re":"anterieur|avant le divorce|niveau de vie|ecole privee","pts":4}],"articles":[{"code":"CF","article":"189","label":"Art. 189 Code de la famille (contenu de l'entretien)","pts":4}],"faille":"La mère ne justifie pas les besoins.","concede":"Les besoins sont établis. Reste à évaluer les ressources."},{"name":"Les ressources du père","adverse":"Le père ne gagne que 9 000 Dirhams par mois.","prompt":"Démontrez les ressources réelles.","options":[{"label":"Preuves des revenus locatifs, expertise","detail":"Le tribunal se fonde sur les preuves produites et peut recourir à des experts.","pts":15,"speech":"Le tribunal se fonde sur les déclarations et les preuves des parties, et peut faire appel à des experts. Nous produisons les annonces de location et les certificats de propriété des deux appartements : les revenus réels du père dépassent largement son salaire déclaré.","ok":["Preuves des revenus cachés","Demande d'expertise"],"ko":[]},{"label":"Supposer des revenus","detail":"Affirmer qu'il gagne plus sans preuve.","pts":6,"speech":"Il gagne certainement plus.","ok":[],"ko":["Aucune preuve"]}],"concepts":[{"label":"Preuves des revenus locatifs","re":"appartement|loyer|location|propriet","pts":5,"key":true},{"label":"Recours à l'expertise","re":"expert","pts":4}],"articles":[{"code":"CF","article":"190","label":"Art. 190 Code de la famille (estimation de la pension)","pts":4}],"faille":"Les revenus supplémentaires ne sont pas prouvés.","concede":"Les revenus locatifs sont établis."},{"name":"Le logement","adverse":"Le père refuse de payer le loyer : la pension suffit.","prompt":"Défendez les frais de logement.","options":[{"label":"Logement distinct de la pension","detail":"Les frais de logement sont distincts de la pension ; le père doit assurer un logement ou payer le loyer.","pts":15,"speech":"Les frais de logement de l'enfant gardé sont distincts de la pension alimentaire et de la rémunération de garde. Le père doit assurer un logement à ses enfants ou s'acquitter du montant du loyer. Nous demandons la prise en charge du loyer de 4 500 Dirhams.","ok":["Le logement s'ajoute à la pension","Chiffre le loyer"],"ko":[]},{"label":"Renoncer au logement","detail":"Abandonner cette demande.","pts":5,"speech":"Nous renonçons au loyer.","ok":[],"ko":["Renonce à un droit distinct"]}],"concepts":[{"label":"Logement distinct de la pension","re":"logement|loyer|distinct","pts":5,"key":true}],"articles":[{"code":"CF","article":"168","label":"Art. 168 Code de la famille (frais de logement)","pts":4}],"faille":"La mère renonce au logement.","concede":"Le logement est dû."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les besoins des enfants, scolarisés en école privée, et les revenus réels du père, incluant des loyers, sont établis ; Par ces motifs : fixe la pension à 6 000 Dirhams par mois et met à sa charge le loyer de 4 500 Dirhams."},{"min":45,"text":"Le Tribunal, attendu que les besoins sont établis mais les ressources partiellement ; Par ces motifs : fixe la pension à 3 500 Dirhams et le logement à 3 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la mère ne justifie ni les besoins ni les ressources alléguées ; Par ces motifs : fixe la pension à 2 000 Dirhams."}]},{"id":"rectification","matiere":"fiscal","title":"Société Négoce Sud c/ Administration fiscale","court":"Tribunal administratif de Marrakech","object":"Contestation d'un redressement d'impôt sur les sociétés de 780 000 DH.","you":"Avocat de la société (Négoce Sud)","adverseName":"Représentant de l'administration fiscale","facts":"Après un contrôle, l'administration a rehaussé le résultat de Négoce Sud. La société n'a reçu qu'une seule notification, puis directement l'avis d'imposition, sans réponse motivée à ses observations envoyées dans les 30 jours. L'administration applique en outre une majoration de 20 %.","rounds":[{"name":"La procédure de rectification","adverse":"Monsieur le Président, la société a été contrôlée et ses écritures sont insuffisantes. L'imposition est fondée.","prompt":"Soulevez le vice de procédure.","options":[{"label":"Procédure normale non respectée","detail":"La procédure normale de rectification impose une réponse de l'administration aux observations du contribuable avant l'imposition.","pts":17,"speech":"Le Code général des impôts organise une procédure normale de rectification contradictoire : notification des motifs et du montant, observations du contribuable dans les trente jours, puis seconde notification motivée de l'administration, avec possibilité de saisir la commission. Ici, la société a répondu dans les délais mais n'a reçu aucune réponse : l'imposition a été émise directement. La procédure est irrégulière.","ok":["Décrit la procédure contradictoire","Relève l'absence de seconde notification","Respect du délai de 30 jours par la société"],"ko":[]},{"label":"Contester les chiffres seulement","detail":"Discuter le montant sans la procédure.","pts":8,"speech":"Le montant est exagéré.","ok":[],"ko":["Néglige le vice de procédure, décisif"]}],"concepts":[{"label":"Procédure contradictoire / seconde notification","re":"seconde notification|reponse|contradictoire|procedure","pts":6,"key":true},{"label":"Observations dans les trente jours","re":"trente|30 jours|observation","pts":4},{"label":"Commission / recours","re":"commission","pts":3}],"articles":[{"code":"CGI","article":"220","label":"Art. 220 CGI (procédure normale de rectification)","pts":5}],"faille":"La société ne soulève aucune irrégularité.","concede":"La procédure est discutable. Reste le fond."},{"name":"La majoration","adverse":"La majoration de 20 % s'applique de plein droit en cas de rectification.","prompt":"Répondez sur la majoration.","options":[{"label":"La majoration suit le sort du redressement","detail":"Si la rectification est irrégulière, la majoration tombe ; à défaut, discuter son taux.","pts":14,"speech":"La majoration prévue en cas de rectification de la base imposable est l'accessoire du redressement : si la procédure de rectification est irrégulière, la majoration tombe avec lui. À titre subsidiaire, nous contestons son application aux chefs de redressement purement d'interprétation.","ok":["Lien accessoire entre majoration et redressement","Argument subsidiaire"],"ko":[]},{"label":"Accepter la majoration","detail":"Ne pas discuter.","pts":5,"speech":"Nous ne contestons pas la majoration.","ok":[],"ko":["Abandon inutile"]}],"concepts":[{"label":"La majoration suit le redressement","re":"accessoire|suit|tombe|majoration","pts":5,"key":true},{"label":"Argument subsidiaire","re":"subsidiair","pts":3}],"articles":[{"code":"CGI","article":"186","label":"Art. 186 CGI (sanctions en cas de rectification)","pts":4}],"faille":"La majoration s'applique.","concede":"La majoration dépend du redressement."},{"name":"Conclusions","adverse":"L'administration propose un abattement de 30 % sur les droits.","prompt":"Concluez.","options":[{"label":"Annulation de l'imposition","detail":"Annulation pour vice de procédure ; subsidiairement, expertise sur le fond.","pts":15,"speech":"Nous concluons à l'annulation de l'imposition et de la majoration pour irrégularité de la procédure. À titre subsidiaire, une expertise comptable sur les chefs de redressement.","ok":["Conclusions hiérarchisées"],"ko":[]},{"label":"Accepter l'abattement","detail":"Transiger.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Renonce à un vice de procédure décisif"]}],"concepts":[{"label":"Annulation pour vice de procédure","re":"annul|vice|irregul","pts":4,"key":true}],"articles":[],"faille":"La société n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'administration n'a pas répondu aux observations du contribuable avant d'émettre l'imposition, en méconnaissance de la procédure normale de rectification ; Par ces motifs : annule l'imposition et la majoration."},{"min":45,"text":"Le Tribunal, attendu que la procédure présente une irrégularité partielle ; Par ces motifs : annule la majoration et ordonne une expertise sur les chefs de redressement."},{"min":0,"text":"Le Tribunal, attendu qu'aucune irrégularité n'est démontrée ; Par ces motifs : rejette la requête."}]}];
